const bookingConfirmationPrompt = (size = "") =>
  `\u0645\u0642\u0627\u0633 ${text(size)} \u0645\u062a\u0627\u062d \u0645\u0639\u0627\u064a\u0627  \u062a\u062d\u0628 \u0623\u062d\u062c\u0632\u0647\u0648\u0644\u0643\u061f`;

const repeatedBookingConfirmationPrompt = () =>
  "\u062a\u0645\u0627\u0645\u060c \u0623\u062d\u062c\u0632\u0647\u0648\u0644\u0643\u061f";

const sizeDigits = (value = "") =>
  text(value)
    .replace(/[\u0660-\u0669]/g, (digit) => String(digit.charCodeAt(0) - 0x0660))
    .replace(/[\u06f0-\u06f9]/g, (digit) => String(digit.charCodeAt(0) - 0x06f0))
    .replace(/[^\d]/g, "");

const isOnlyShoeSizeMessage = (message = "", size = "") => {
  const messageDigits = sizeDigits(message);
  const selectedDigits = sizeDigits(size);
  if (!messageDigits || !selectedDigits || messageDigits !== selectedDigits) return false;
  return !text(message).replace(/[\d\u0660-\u0669\u06f0-\u06f9\s.,،:;!؟?()-]/g, "");
};

const normalizeEgyptPhone = (value = "") => {
  const rawPhone = text(value);
  const normalized = rawPhone
    .replace(/[\u0660-\u0669]/g, (digit) => String(digit.charCodeAt(0) - 0x0660))
    .replace(/[\u06f0-\u06f9]/g, (digit) => String(digit.charCodeAt(0) - 0x06f0));
  const digitsOnly = normalized.replace(/[^\d]/g, "");
  let parsedPhone = "";
  if (/^01[0125]\d{8}$/.test(digitsOnly)) {
    parsedPhone = digitsOnly;
  } else if (/^201[0125]\d{8}$/.test(digitsOnly)) {
    parsedPhone = `0${digitsOnly.slice(2)}`;
  } else if (/^00201[0125]\d{8}$/.test(digitsOnly)) {
    parsedPhone = `0${digitsOnly.slice(4)}`;
  } else {
    const match = normalized.match(/(?:\+?20|0020)?\s*(01[0125][\s-]?\d{4}[\s-]?\d{4})/);
    parsedPhone = match ? match[1].replace(/[^\d]/g, "") : "";
  }
  if (rawPhone) {
    console.log("SOCIAL_COMMENT_PHONE_PARSE_TRACE", {
      raw_phone: rawPhone,
      parsed_phone: parsedPhone,
    });
  }
  return parsedPhone;
};

const parseCheckoutCustomerDetails = (messageText = "") => {
  const raw = text(messageText);
  const normalizedMessage = String(messageText ?? "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/\n{2,}/g, "\n")
    .replace(/[ \t]+/g, " ");
  const phone = normalizeEgyptPhone(normalizedMessage || raw);
  const lines = normalizedMessage
    .split("\n")
    .map((line) => text(line))
    .filter(Boolean);
  const fallbackSegments = raw
    .split(/،|,/)
    .map((line) => text(line))
    .filter(Boolean);
  const effectiveLines = lines.length ? lines : fallbackSegments;
  const phoneLineIndex = effectiveLines.findIndex((line) => normalizeEgyptPhone(line));
  const governorateLineIndex = effectiveLines.findIndex((line) => extractSalesGovernorate(line));
  const phonePattern = /(?:\+?20|0020)?\s*01[0125][\s-]?\d{4}[\s-]?\d{4}/g;
  const withoutPhone = (value = "") => text(String(value || "").replace(phone, "").replace(phonePattern, ""));
  const governorateCandidate = withoutPhone(
    governorateLineIndex >= 0
      ? extractSalesGovernorate(effectiveLines[governorateLineIndex])
      : extractSalesGovernorate(normalizedMessage || raw)
  );
  const nonPhoneLines = effectiveLines.filter((line) => !normalizeEgyptPhone(line));
  const nameCandidate = withoutPhone(
    effectiveLines.find((line, index) =>
      index !== governorateLineIndex &&
      !normalizeEgyptPhone(line) &&
      line.length <= 120 &&
      !/(شارع|بجوار|منطقة|محافظة|مدينة|عمارة|دور|شقة|address|street)/i.test(line)
    ) || ""
  );
  const addressLines = governorateLineIndex >= 0
    ? effectiveLines.slice(governorateLineIndex + 1)
    : phoneLineIndex >= 0
      ? effectiveLines.slice(phoneLineIndex + 1)
      : nonPhoneLines.filter((line) => line !== nameCandidate);
  const addressCandidate = withoutPhone(addressLines.join(" "));
  const fallbackAddress = withoutPhone((normalizedMessage || raw))
    .replace(nameCandidate, "")
    .replace(governorateCandidate, "")
    .trim();
  const nameGuard = guardAiNameCapture({ messageText: nameCandidate || raw, route: "meta_checkout_parser" });
  return {
    customer_name: nameGuard.blockedAsName ? "" : nameCandidate.slice(0, 120),
    customer_phone: phone,
    governorate: governorateCandidate.slice(0, 80),
    customer_address: (addressCandidate || fallbackAddress).slice(0, 500),
  };
};

export const evaluateMetaCheckoutContinuation = ({ memory = {}, messageText = "" } = {}) => {
  const previousCheckoutStage = text(memory.checkoutStage || "browsing");
  const selectedSize = text(memory.selectedSize || "");
  const selectedProductId = memory.selectedProductId || memory.lastProductCard?.product_id || null;
  const bookingConfirmationAsked = memory.bookingConfirmationAsked === true;
  const requestedSize = extractShoeSize(messageText) || "";
  const sameSizeRepeated = Boolean(
    requestedSize &&
    selectedSize &&
    sizeDigits(requestedSize) === sizeDigits(selectedSize) &&
    isOnlyShoeSizeMessage(messageText, requestedSize)
  );
  const confirmationDetected = detectExplicitCheckoutIntent(messageText) ||
    (bookingConfirmationAsked && detectReservationAffirmation(messageText) && !requestedSize);
  const explicitSizeChange = detectExplicitSizeChange(messageText);
  const eligible = Boolean(
    selectedProductId &&
    selectedSize &&
    checkoutStageAtLeast(previousCheckoutStage, "product_details") &&
    !checkoutStageAtLeast(previousCheckoutStage, "checkout") &&
    !explicitSizeChange
  );

  if (!eligible) {
    return {
      handled: false,
      branch: "not_checkout_continuation",
      previousCheckoutStage,
      requestedSize,
      selectedSize,
      bookingConfirmationAsked,
      confirmationDetected,
      explicitSizeChange,
    };
  }

  if (confirmationDetected) {
    return {
      handled: true,
      branch: "booking_confirmation_to_checkout_info",
      previousCheckoutStage,
      nextCheckoutStage: "checkout",
      selectedProductId,
      selectedSize,
      bookingConfirmationAsked: true,
      confirmationDetected,
      repeatedSameSize: sameSizeRepeated,
      replyText: CHECKOUT_INFO_COLLECTION_REPLY,
      skipGenericSizeFlowReason: "checkout_continuation_has_selected_size",
    };
  }

  if (sameSizeRepeated) {
    return {
      handled: true,
      branch: "repeat_same_size_booking_prompt",
      previousCheckoutStage,
      nextCheckoutStage: "product_details",
      selectedProductId,
      selectedSize,
      bookingConfirmationAsked,
      confirmationDetected: false,
      repeatedSameSize: true,
      replyText: "\u0623\u064a\u0648\u0647\u060c \u0627\u0644\u0645\u0642\u0627\u0633 \u0645\u062a\u0648\u0641\u0631 \u2705\n\u062a\u062d\u0628 \u0623\u0642\u0648\u0644\u0643 \u0627\u0644\u0633\u0639\u0631 \u0623\u0648 \u0623\u0648\u0631\u064a\u0643 \u0644\u0648\u0646 \u062a\u0627\u0646\u064a\u061f",
      skipGenericSizeFlowReason: "same_selected_size_repeated",
    };
  }

  return {
    handled: false,
    branch: "waiting_for_booking_confirmation",
    previousCheckoutStage,
    selectedProductId,
    selectedSize,
    bookingConfirmationAsked,
    confirmationDetected: false,
    repeatedSameSize: false,
  };
};

const normalizeCheckoutGuardText = (value = "") =>
  text(value)
    .toLowerCase()
    .replace(/[\u064b-\u065f\u0670\u0640]/g, "")
    .replace(/[\u0623\u0625\u0622]/g, "\u0627")
    .replace(/\u0649/g, "\u064a")
    .replace(/\u0629/g, "ه")
    .replace(/[^\p{L}\p{N}\s]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();

const checkoutConfirmationOnly = (message = "") => {
  const normalized = normalizeCheckoutGuardText(message);
  if (!normalized) return false;
  return /^(?:تمام|اوكي|اوك|ايوه|ايوا|ماشي|احجزه|احجزها|احجزهولي|احجزهولي|هاته|هاتها|هات|اكمل|كمل|yes|ok|okay|continue|book it|reserve it)(?:\s+(?:تمام|اوكي|اوك|ايوه|ايوا|ماشي|احجزه|احجزها|احجزهولي|هاته|هاتها|هات|اكمل|كمل|please|بليز|لو سمحت))*$/.test(normalized);
};

const QUESTION_TYPES = Object.freeze({
  AVAILABILITY_QUESTION: "AVAILABILITY_QUESTION",
  PRICE_QUESTION: "PRICE_QUESTION",
  SIZE_QUESTION: "SIZE_QUESTION",
  COLOR_QUESTION: "COLOR_QUESTION",
  MORE_IMAGES: "MORE_IMAGES",
  GREETING: "GREETING",
  LINK_QUESTION: "LINK_QUESTION",
  ALTERNATIVES_QUESTION: "ALTERNATIVES_QUESTION",
  BUYING_INTENT: "BUYING_INTENT",
  GENERAL_PRODUCT_QUESTION: "GENERAL_PRODUCT_QUESTION",
});

const resolveCustomerQuestion = ({ message = {}, memory = {} } = {}) => {
  const messageText = text(typeof message === "string" ? message : message?.message_text || "");
  const normalized = normalizeCheckoutGuardText(messageText);
  const hasImage = typeof message === "object" && imageAttachments(message.attachments || []).length > 0;
  const explicitSize = extractShoeSize(messageText) || "";
  const hasSizeKeyword = /\bsize\b/i.test(messageText) || hasTerm(messageText, ["مقاس", "مقاسات"]);
  const topicEntities = detectContextTopicEntities(messageText);
  let intent = QUESTION_TYPES.GENERAL_PRODUCT_QUESTION;
  let reason = "general_product_question";

  const resolvedColorQuestion = isColorQuestionMessage(messageText) || Boolean(detectSelectionColor(messageText) || detectExplicitColor(messageText));
  const resolvedMoreImages = Boolean(detectMoreImagesRequest(messageText) && !resolvedColorQuestion);
  const resolvedLinkQuestion = detectProductLinkRequest(messageText);
  const resolvedGreeting = detectGreetingMessage(messageText);
  const affirmativeFollowup = detectShortAffirmativeReply(messageText) ? resolveShortAffirmativeFollowup({ messageText, memory }) : null;
  if (resolvedGreeting) {
    intent = QUESTION_TYPES.GREETING;
    reason = "greeting";
  } else if (affirmativeFollowup?.intent === AI_INTENTS.MORE_IMAGES) {
    intent = QUESTION_TYPES.MORE_IMAGES;
    reason = affirmativeFollowup.reason;
  } else if (affirmativeFollowup?.intent === AI_INTENTS.ALTERNATIVES) {
    intent = QUESTION_TYPES.ALTERNATIVES_QUESTION;
    reason = affirmativeFollowup.reason;
  } else if (affirmativeFollowup?.intent === AI_INTENTS.SIZE_CHECK) {
    intent = QUESTION_TYPES.SIZE_QUESTION;
    reason = affirmativeFollowup.reason;
  } else if (affirmativeFollowup?.intent === AI_INTENTS.PRODUCT_PRESENTATION) {
    intent = QUESTION_TYPES.GENERAL_PRODUCT_QUESTION;
    reason = affirmativeFollowup.reason;
  } else if (resolvedColorQuestion) {
    intent = QUESTION_TYPES.COLOR_QUESTION;
    reason = "color_request";
  } else if (resolvedMoreImages) {
    intent = QUESTION_TYPES.MORE_IMAGES;
    reason = "more_images_request";
  } else if (resolvedLinkQuestion) {
    intent = QUESTION_TYPES.LINK_QUESTION;
    reason = "link_request";
  } else if (detectAlternativesRequest(messageText)) {
    intent = QUESTION_TYPES.ALTERNATIVES_QUESTION;
    reason = "alternatives_request";
  } else if (/لينك|اللينك|رابط|الرابط|link|url/i.test(messageText)) {
    intent = QUESTION_TYPES.LINK_QUESTION;
    reason = "link_request";
  } else if (explicitSize || (hasSizeKeyword && !topicEntities.topic)) {
    intent = QUESTION_TYPES.SIZE_QUESTION;
    reason = explicitSize ? "explicit_size_question" : "size_keyword_question";
  } else if (/كام|بكام|السعر|سعره|price|how much/i.test(messageText)) {
    intent = QUESTION_TYPES.PRICE_QUESTION;
    reason = "price_question";
  } else if (checkoutConfirmationOnly(messageText) || detectBuyingIntent(messageText)) {
    intent = QUESTION_TYPES.BUYING_INTENT;
    reason = "buying_or_checkout_confirmation";
  } else if (hasImage || topicEntities.topic || /فيه|موجود|متاح|available|عندك/i.test(normalized)) {
    intent = QUESTION_TYPES.AVAILABILITY_QUESTION;
    reason = hasImage ? "image_availability_question" : topicEntities.topic ? "product_availability_question" : "availability_keyword";
  }

  console.log("[color-router]", {
    message: messageText,
    resolvedColorQuestion,
    activeProductId: memory.activeProductId || memory.selectedProductId || memory.lastProductCard?.product_id || memory.lastProductCard?.id || null,
  });
  console.log("[more-images-router]", {
    message: messageText,
    resolvedQuestionType: intent,
    blockedPresentation: intent === QUESTION_TYPES.MORE_IMAGES,
    imageCount: 0,
  });
  console.log("[visual-followup-router]", {
    message: messageText,
    resolvedQuestionType: intent,
    activeProductId: memory.activeProductId || memory.selectedProductId || memory.lastProductCard?.product_id || memory.lastProductCard?.id || null,
    blockedAvailabilityReply: [QUESTION_TYPES.COLOR_QUESTION, QUESTION_TYPES.MORE_IMAGES, QUESTION_TYPES.LINK_QUESTION].includes(intent),
    reason,
  });

  return {
    intent,
    reason,
    message: messageText,
    explicitSize,
    usedPreferredSize: false,
    usedSelectedSize: intent === QUESTION_TYPES.SIZE_QUESTION && Boolean(memory.selectedSize),
    usedActiveSize: intent === QUESTION_TYPES.SIZE_QUESTION && Boolean(memory.activeSize),
  };
};

const logQuestionResolver = (resolved = {}) => {
  console.log("[question-resolver]", {
    message: resolved.message || "",
    intent: resolved.intent || "",
    usedPreferredSize: resolved.usedPreferredSize === true,
    usedSelectedSize: resolved.usedSelectedSize === true,
    usedActiveSize: resolved.usedActiveSize === true,
  });
};

let inboundMessageSequenceCounter = 0;
const inboundReplyFinalization = new Map();

const lifecycleMessageId = (message = {}) =>
  text(message.messageLifecycleId || message.external_message_id || message.dedupe_key || inboundIdempotencyKey(message) || "");

const assignInboundMessageLifecycle = (message = {}) => {
  const messageId = lifecycleMessageId(message) || `${text(message.channel || "meta")}:${text(message.external_conversation_id || "unknown")}:${Date.now()}`;
  inboundMessageSequenceCounter += 1;
  message.messageLifecycleId = messageId;
  message.messageSequenceId = inboundMessageSequenceCounter;
  console.log("[inbound-message]", {
    messageId,
    messageSequenceId: message.messageSequenceId,
    message: text(message.message_text || "[attachment]").slice(0, 240),
    timestamp: message.timestamp || nowIso(),
  });
  return { messageId, messageSequenceId: message.messageSequenceId };
};

const finalReplyPipelineId = ({ message = {}, owner = "", replyType = "" } = {}) =>
  text(message.finalReplyPipelineId || message.replyPipelineId || `${lifecycleMessageId(message)}:${owner || "response_orchestrator"}:${replyType || "final_reply"}`);

const isInboundReplyFinalized = (message = {}) => {
  const key = lifecycleMessageId(message);
  return Boolean(key && inboundReplyFinalization.has(key));
};

const finalizeInboundReplyPipeline = ({ message = {}, owner = "response_orchestrator", replyType = "text", replyPreview = "", pipelineId = "" } = {}) => {
  const key = lifecycleMessageId(message);
  if (!key) return { allowed: true, finalized: false, reason: "missing_message_id" };
  const safePipelineId = text(pipelineId) || finalReplyPipelineId({ message, owner, replyType });
  const existing = inboundReplyFinalization.get(key);
  if (existing && existing.pipelineId !== safePipelineId) {
    console.log("[reply-finalized]", {
      messageId: key,
      messageSequenceId: message.messageSequenceId || null,
      owner: existing.owner || "",
      replyType: existing.replyType || "",
      blockedOwner: owner || "",
      blockedReplyType: replyType || "",
      blocked: true,
      timestamp: nowIso(),
    });
    return { allowed: false, finalized: true, reason: "final_reply_already_generated", existing };
  }
  if (!existing) {
    const record = {
      owner,
      replyType,
      pipelineId: safePipelineId,
      replyPreview: text(replyPreview).slice(0, 180),
      timestamp: nowIso(),
      messageSequenceId: message.messageSequenceId || null,
    };
    inboundReplyFinalization.set(key, record);
    console.log("[reply-finalized]", {
      messageId: key,
      messageSequenceId: record.messageSequenceId,
      owner: record.owner,
      replyType: record.replyType,
      timestamp: record.timestamp,
    });
    return { allowed: true, finalized: true, reason: "final_reply_pipeline_started", existing: record };
  }
  return { allowed: true, finalized: true, reason: "same_reply_pipeline", existing };
};

const replySourceForIntent = (detectedIntent = "", metadata = {}) => {
  const explicit = text(metadata.replySource || metadata.reply_source);
  if (explicit) return explicit;
  const intent = text(detectedIntent);
  if (/product_search|model_color_limit_intro/i.test(intent)) return "product_search_handler";
  if (/size|availability/i.test(intent)) return "size_check_handler";
  if (/checkout|order|draft/i.test(intent)) return "checkout_handler";
  if (/other_colors|color/i.test(intent)) return "color_handler";
  if (/fallback|clarification|blocked/i.test(intent)) return "fallback_handler";
  return "handler";
};

const logReplyPath = ({
  handler = "",
  intent = "",
  replySource = "",
  replyPath = [],
  orchestratorUsed = true,
  resolvedQuestionType = "",
  conversationId = "",
} = {}) => {
  const path = Array.isArray(replyPath) && replyPath.length
    ? replyPath
    : ["question_resolver", "response_orchestrator", replySource || handler || "final_reply"];
  console.log("[reply-path]", {
    handler: handler || "",
    intent: intent || "",
    reply_source: replySource || "",
    replySource: replySource || "",
    replyPath: path,
    orchestratorUsed: orchestratorUsed === true,
    resolvedQuestionType: resolvedQuestionType || "",
    conversation_id: conversationId || "",
  });
};

const orchestrateFinalReply = ({ message = {}, replyText = "", productCards = [], detectedIntent = "", metadata = {} } = {}) => {
  const memory = getConversationMemory(message.external_conversation_id) || {};
  const resolvedQuestion = message.resolvedQuestion || memory.resolvedQuestion || resolveCustomerQuestion({ message, memory });
  const replySource = replySourceForIntent(detectedIntent, metadata);
  const handler = text(metadata.handler || metadata.reply_handler || replySource);
  const ownedReply = ensureResponseOrchestratorReply({
    message,
    replyText,
    detectedIntent,
    metadata: {
      ...metadata,
      handler,
      originalReplySource: replySource,
      original_reply_source: replySource,
      resolvedQuestionType: resolvedQuestion.intent || metadata.resolvedQuestionType || "",
      resolved_question_type: resolvedQuestion.intent || metadata.resolved_question_type || "",
      replyDecisionReason: resolvedQuestion.reason || metadata.replyDecisionReason || "",
    },
  });
  const finalMetadata = {
    ...ownedReply.metadata,
    replyOwner: "response_orchestrator",
    reply_owner: "response_orchestrator",
    replySource: "response_orchestrator",
    reply_source: "response_orchestrator",
    originalReplySource: replySource,
    original_reply_source: replySource,
    replyPath: ownedReply.path || ["question_resolver", handler, "response_orchestrator", "final_reply"],
    reply_path: ownedReply.path || ["question_resolver", handler, "response_orchestrator", "final_reply"],
    orchestratorUsed: true,
    orchestrator_used: true,
    resolvedQuestionType: resolvedQuestion.intent || "",
    resolved_question_type: resolvedQuestion.intent || "",
    replyDecisionReason: resolvedQuestion.reason || metadata.replyDecisionReason || "",
  };
  logReplyPath({
    handler,
    intent: detectedIntent,
    replySource: "response_orchestrator",
    replyPath: finalMetadata.replyPath,
    orchestratorUsed: true,
    resolvedQuestionType: resolvedQuestion.intent || "",
    conversationId: message.external_conversation_id,
  });
  logReplyOwner({
    handler: "response_orchestrator",
    intent: detectedIntent,
    message,
    replyText: ownedReply.text,
    metadata: finalMetadata,
  });
  const protectedV2Intent = /^(product_search|more_images|product_presentation|size_followup|SIZE_FOLLOWUP|color_followup|COLOR_AVAILABILITY_FROM_SIZE|color_selected|COLOR_SELECTED|post_product_size_selected|POST_PRODUCT_SIZE_SELECTED|post_product_color_list|POST_PRODUCT_COLOR_LIST|post_product_color_selected|POST_PRODUCT_COLOR_SELECTED|post_product_order_confirmation|POST_PRODUCT_ORDER_CONFIRMATION)$/i.test(text(detectedIntent));
  if (protectedV2Intent || metadata.preserveReplyText === true || finalMetadata.protectedV2Intent === true) {
    return {
      text: ownedReply.text,
      productCards,
      metadata: {
        ...finalMetadata,
        compressionApplied: false,
        suppressedFields: [],
        protectedV2Intent: true,
      },
      resolvedQuestion,
    };
  }
  const compressed = compactReplyTextForConversation({
    conversationId: message.external_conversation_id,
    message,
    replyText: ownedReply.text,
    productCards,
    detectedIntent,
    metadata: finalMetadata,
  });
  const compressionMetadata = compressed.diagnostics.compressionApplied
    ? {
        compressionApplied: true,
        compression_applied: true,
        suppressedFields: compressed.diagnostics.suppressedFields,
        suppressed_fields: compressed.diagnostics.suppressedFields,
        compressionReason: compressed.diagnostics.reason,
        compression_reason: compressed.diagnostics.reason,
      }
    : { compressionApplied: false, suppressedFields: [] };
  return {
    text: compressed.text,
    productCards,
    metadata: { ...finalMetadata, ...compressionMetadata },
    resolvedQuestion,
  };
};

const sizeGuardProductRequestTerms = [
  "jordan",
  "air jordan",
  "aj4",
  "j4",
  "nike",
  "adidas",
  "superstar",
  "super star",
  "north face",
  "northface",
  "\u062c\u0648\u0631\u062f\u0646",
  "\u0646\u0627\u064a\u0643",
  "\u0627\u062f\u064a\u062f\u0627\u0633",
  "\u0623\u062f\u064a\u062f\u0627\u0633",
  "\u0633\u0648\u0628\u0631 \u0633\u062a\u0627\u0631",
  "\u0646\u0648\u0631\u062b \u0641\u064a\u0633",
  "\u0646\u0648\u0631\u062a \u0641\u064a\u0633",
];

const sizeGuardSignals = (message = "", memory = {}) => {
  const messageText = text(message);
  const explicitSize = extractShoeSize(messageText) || "";
  const hasSizeKeyword = /\bsize\b/i.test(messageText) || hasTerm(messageText, ["\u0645\u0642\u0627\u0633", "\u0645\u0642\u0627\u0633\u0627\u062a"]);
  const topicEntities = detectContextTopicEntities(messageText);
  const hasNewProductContext = Boolean(topicEntities.productName || topicEntities.model || topicEntities.brand);
  const hasProductRequest = Boolean(
    hasNewProductContext ||
    detectModelNameSearch(messageText) ||
    detectNorthFaceCorrection(messageText) ||
    hasTerm(messageText, sizeGuardProductRequestTerms)
  );
  const hasColorRequest = Boolean(
    detectOtherColorsRequest(messageText) ||
    detectAllColorsRequest(messageText) ||
    detectSelectionColor(messageText) ||
    detectExplicitColor(messageText)
  );
  const hasVisualCorrection = Boolean(detectVisualCorrectionTextV3(messageText));
  const hasExplicitSize = Boolean(explicitSize || hasSizeKeyword);
  const confirmationOnly = checkoutConfirmationOnly(messageText);
  const memorySize = text(memory?.selectedSize || memory?.activeSize || "");
  const checkoutStage = normalizeCheckoutStage(memory?.checkoutStage || memory?.buyingStage || "");
  return {
    messageText,
    explicitSize,
    hasExplicitSize,
    hasSizeKeyword,
    hasProductRequest,
    hasColorRequest,
    hasVisualCorrection,
    confirmationOnly,
    memorySize,
    checkoutStage,
  };
};

const logSizeGuard = ({
  message = "",
  hasExplicitSize = false,
  reusedMemorySize = false,
  blockedOldSize = false,
  reason = "",
  memorySize = "",
} = {}) => {
  console.log("[size-guard]", {
    message: text(message),
    hasExplicitSize: Boolean(hasExplicitSize),
    reusedMemorySize: Boolean(reusedMemorySize),
    blockedOldSize: Boolean(blockedOldSize),
    reason: reason || "",
    memorySize: text(memorySize),
  });
};

const shouldRunSizeCheck = (message = "", memory = {}) => {
  const signals = sizeGuardSignals(typeof message === "string" ? message : message?.message_text || "", memory);
  const resolved = memory?.resolvedQuestion || resolveCustomerQuestion({ message: typeof message === "string" ? { message_text: message } : message, memory });
  let reason = "no_explicit_size_intent";
  let allowed = false;
  if (resolved.intent !== QUESTION_TYPES.SIZE_QUESTION) reason = `resolved_${resolved.intent || "UNKNOWN"}`;
  else if (signals.hasColorRequest) reason = "color_request";
  else if ((signals.hasProductRequest || signals.hasVisualCorrection) && !signals.hasExplicitSize) reason = "product_search_without_size";
  else if (signals.hasExplicitSize) {
    allowed = true;
    reason = signals.explicitSize ? "explicit_size" : "size_keyword";
  }
  logSizeGuard({
    message: signals.messageText,
    hasExplicitSize: signals.hasExplicitSize,
    reusedMemorySize: false,
    blockedOldSize: Boolean(!allowed && signals.memorySize),
    reason,
    memorySize: signals.memorySize,
  });
  return { allowed, reason, ...signals };
};

const shouldReuseSelectedSize = (message = "", memory = {}) => {
  const signals = sizeGuardSignals(typeof message === "string" ? message : message?.message_text || "", memory);
  const resolved = memory?.resolvedQuestion || resolveCustomerQuestion({ message: typeof message === "string" ? { message_text: message } : message, memory });
  let reason = "no_memory_size";
  let allowed = false;
  if (!signals.memorySize) reason = "no_memory_size";
  else if (resolved.intent === QUESTION_TYPES.SIZE_QUESTION && signals.hasExplicitSize) {
    allowed = true;
    reason = "explicit_size_in_message";
  } else if (![QUESTION_TYPES.SIZE_QUESTION, QUESTION_TYPES.BUYING_INTENT].includes(resolved.intent) && !signals.confirmationOnly) {
    reason = `resolved_${resolved.intent || "UNKNOWN"}`;
  } else if (signals.hasColorRequest) reason = "color_request";
  else if (signals.hasProductRequest || signals.hasVisualCorrection) reason = "new_product_search";
  else if (
    signals.confirmationOnly &&
    (memory?.bookingConfirmationAsked === true || checkoutStageAtLeast(signals.checkoutStage, "size_selected") || checkoutStageAtLeast(signals.checkoutStage, "product_details"))
  ) {
    allowed = true;
    reason = "checkout_confirmation";
  } else if (checkoutStageAtLeast(signals.checkoutStage, "checkout") && !signals.hasColorRequest && !signals.hasProductRequest) {
    allowed = true;
    reason = "active_checkout";
  } else {
    reason = "not_checkout_confirmation";
  }
  logSizeGuard({
    message: signals.messageText,
    hasExplicitSize: signals.hasExplicitSize,
    reusedMemorySize: allowed && Boolean(signals.memorySize),
    blockedOldSize: !allowed && Boolean(signals.memorySize),
    reason,
    memorySize: signals.memorySize,
  });
  return { allowed, reason, ...signals };
};

const shouldContinueCheckout = (message = {}, memory = {}) => {
  const messageText = text(typeof message === "string" ? message : message?.message_text || "");
  const attachments = typeof message === "object" ? message.attachments || [] : [];
  const topicEntities = detectContextTopicEntities(messageText);
  const hasImage = imageAttachments(attachments).length > 0;
  const hasNewProductContext = Boolean(topicEntities.productName || topicEntities.model || topicEntities.brand);
  const hasGreeting = detectGreetingMessage(messageText);
  const hasColorRequest = Boolean(isColorQuestionMessage(messageText) || detectSelectionColor(messageText) || detectExplicitColor(messageText));
  const hasMoreImages = Boolean(detectMoreImagesRequest(messageText) && !hasColorRequest);
  const hasAlternatives = Boolean(detectAlternativesRequest(messageText));
  const hasVisualSearch = hasImage || Boolean(detectVisualCorrectionTextV3(messageText));
  const confirmationOnly = checkoutConfirmationOnly(messageText);
  const reuseSize = shouldReuseSelectedSize(messageText, memory);
  let reason = "not_confirmation";
  let continueCheckout = false;

  if (!memory?.selectedSize && !memory?.activeSize) reason = "no_selected_size";
  else if (hasGreeting) reason = "greeting_message";
  else if (hasImage) reason = "image_message";
  else if (hasVisualSearch) reason = "visual_search_message";
  else if (hasNewProductContext) reason = "new_product_brand_or_model";
  else if (hasMoreImages) reason = "more_images_request";
  else if (hasColorRequest) reason = "color_request";
  else if (hasAlternatives) reason = "alternatives_request";
  else if (confirmationOnly && reuseSize.allowed) {
    reason = "checkout_confirmation";
    continueCheckout = true;
  }

  return {
    continueCheckout,
    reason,
    message: messageText,
    confirmationOnly,
    hasNewProductContext,
    hasGreeting,
    hasMoreImages,
    hasColorRequest,
    hasAlternatives,
    hasVisualSearch,
  };
};

const extractImageUrlFromAttachment = (attachment = {}) => {
  if (!attachment || typeof attachment !== "object") return "";
  const direct = text(
    attachment.url ||
      attachment.image_url ||
      attachment.imageUrl ||
      attachment.secure_url ||
      attachment.src ||
      attachment.href ||
      attachment.payload?.url ||
      attachment.payload?.image_url ||
      attachment.payload?.imageUrl ||
      attachment.payload?.attachment_url ||
      attachment.media?.image?.src ||
      attachment.media?.src ||
      attachment.image?.url ||
      attachment.image?.src ||
      attachment.preview_url
  );
  if (direct) return direct;
  for (const value of Object.values(attachment)) {
    if (value && typeof value === "object") {
      const nested = extractImageUrlFromAttachment(value);
      if (nested) return nested;
    }
  }
  return "";
};

const imageAttachments = (attachments = []) =>
  (Array.isArray(attachments) ? attachments : [])
    .map((attachment) => ({ ...attachment, url: extractImageUrlFromAttachment(attachment) }))
    .filter((attachment) => {
      const type = text(attachment?.type || attachment?.mime_type || attachment?.content_type).toLowerCase();
      const url = text(attachment?.url);
      return url && (type.includes("image") || /\.(png|jpe?g|webp|gif)(?:[?#].*)?$/i.test(url) || /\/image\//i.test(url));
    })
    .slice(0, 6);

const detectFaqIntent = (message = "") => {
  const normalized = text(message).toLowerCase();
  if (hasTerm(normalized, ["كاش", "فيزا", "دفع عند الاستلام", "الدفع عند الاستلام", "cod"])) return "payment";
  if (hasTerm(normalized, ["توصيل كام", "الشحن كام", "شحن كام", "التوصيل كام", "تكلفة الشحن"])) return "delivery";
  if (hasTerm(normalized, ["بيرجع", "استبدال", "استرجاع", "ينفع ارجع", "ينفع أرجع"])) return "exchange";
  return "";
};

const readableArabicSetting = (value = "") => {
  const safe = text(value);
  return /[\u0600-\u06FF]/.test(safe) ? safe : "";
};

const imageIdentity = (url = "") =>
  text(url)
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/[?#].*$/, "")
    .replace(/\/+$/g, "");

const hashDedupe = (value = "") => crypto.createHash("sha256").update(text(value)).digest("hex");
const normalizeDedupeText = (value = "") =>
  text(value).toLowerCase().replace(/\s+/g, " ").replace(/[^\p{L}\p{N}\s]+/gu, "").trim();

const timestampBucket = (value = "") => {
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed)) return "";
  return String(Math.floor(parsed / (5 * 60 * 1000)));
};

const inboundIdempotencyKey = (message = {}) => {
  const metaId = text(message.external_message_id || message.dedupe_key || message.raw?.event?.message?.mid || message.raw?.event?.message?.id);
  if (metaId) return `mid:${metaId}`;
  const attachmentUrl = imageAttachmentUrls(message.attachments || [])[0] || "";
  const parts = [
    message.channel,
    message.external_conversation_id || message.conversation_id,
    message.external_customer_id,
    normalizeDedupeText(message.message_text),
    imageIdentity(attachmentUrl),
    timestampBucket(message.timestamp),
  ].map(text);
  if (!parts.some(Boolean)) return "";
  return `fallback:${hashDedupe(parts.join("|"))}`;
};

const loadConversationMetadata = async ({ tenantId, channel = "", conversationId = "" } = {}) => {
  if (!tenantId || !conversationId) return {};
  const result = await db.query(
    `
    SELECT metadata
    FROM ai_channel_conversations
    WHERE tenant_id = $1
      AND external_conversation_id = $2
      AND ($3::text = '' OR channel = $3 OR channel = 'facebook_messenger' OR $3 = 'facebook_messenger')
    ORDER BY updated_at DESC
    LIMIT 1
    `,
    [numberOrNull(tenantId), text(conversationId), text(channel)]
  ).catch(() => ({ rows: [] }));
  return result.rows[0]?.metadata && typeof result.rows[0].metadata === "object" ? result.rows[0].metadata : {};
};

const recentMetaArray = (metadata = {}, key = "") => Array.isArray(metadata?.[key]) ? metadata[key] : [];

const hasProcessedInboundKey = async ({ tenantId, channel = "", conversationId = "", inboundKey = "" } = {}) => {
  if (!inboundKey) return false;
  const metadata = await loadConversationMetadata({ tenantId, channel, conversationId });
  return recentMetaArray(metadata, "ai_processed_inbound_keys").some((item) => text(item?.key || item) === inboundKey);
};

const storeProcessedInboundKey = async ({ tenantId, channel = "", conversationId = "", inboundKey = "", status = "sent" } = {}) => {
  if (!tenantId || !conversationId || !inboundKey) return null;
  const metadata = await loadConversationMetadata({ tenantId, channel, conversationId });
  const recent = recentMetaArray(metadata, "ai_processed_inbound_keys")
    .filter((item) => text(item?.key || item) && text(item?.key || item) !== inboundKey)
    .slice(-49);
  recent.push({ key: inboundKey, status, at: nowIso() });
  await db.query(
    `
    UPDATE ai_channel_conversations
    SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{ai_processed_inbound_keys}', $4::jsonb, true),
        updated_at = NOW()
    WHERE tenant_id = $1
      AND external_conversation_id = $2
      AND ($3::text = '' OR channel = $3 OR channel = 'facebook_messenger' OR $3 = 'facebook_messenger')
    `,
    [numberOrNull(tenantId), text(conversationId), text(channel), json(recent)]
  ).catch((error) => {
    console.warn("[ai-dedupe] store processed key failed", {
      tenant_id: tenantId,
      conversation_id: conversationId,
      message: error?.message || "failed",
    });
  });
  console.log("[ai-dedupe] stored processed key", {
    tenant_id: tenantId,
    conversation_id: conversationId,
    inbound_key: inboundKey,
    status,
  });
  return recent;
};

const storeSentProductMessages = async ({ tenantId, channel = "", conversationId = "", sentProductMessages = [] } = {}) => {
  if (!tenantId || !conversationId || !sentProductMessages.length) return null;
  const metadata = await loadConversationMetadata({ tenantId, channel, conversationId });
  const current = recentMetaArray(metadata, "ai_sent_product_messages")
    .filter((item) => text(item?.outbound_message_id))
    .slice(-80);
  const byMessageId = new Map(current.map((item) => [text(item.outbound_message_id), item]));
  for (const item of sentProductMessages) {
    const outboundMessageId = text(item.outbound_message_id);
    if (!outboundMessageId) continue;
    byMessageId.set(outboundMessageId, {
      outbound_message_id: outboundMessageId,
      productId: item.productId || null,
      variantId: item.variantId || null,
      color: text(item.color),
      imageUrl: text(item.imageUrl),
      title: text(item.title),
      sizes: Array.isArray(item.sizes) ? item.sizes.map(text).filter(Boolean) : [],
      sentAt: item.sentAt || nowIso(),
    });
  }
  const next = [...byMessageId.values()].slice(-100);
  await db.query(
    `
    UPDATE ai_channel_conversations
    SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{ai_sent_product_messages}', $4::jsonb, true),
        updated_at = NOW()
    WHERE tenant_id = $1
      AND external_conversation_id = $2
      AND ($3::text = '' OR channel = $3 OR channel = 'facebook_messenger' OR $3 = 'facebook_messenger')
    `,
    [numberOrNull(tenantId), text(conversationId), text(channel), json(next)]
  ).catch((error) => {
    console.warn("[reply-context] sent product metadata store failed", {
      tenant_id: tenantId,
      conversation_id: conversationId,
      message: error?.message || "",
    });
  });
  return next;
};

const outboundDedupeContextFromMessage = (message = {}, overrides = {}) => {
  const inboundMetaMid = text(overrides.inboundMetaMid || message.external_message_id || message.raw?.event?.message?.mid || message.dedupe_key || "");
  let inboundKey = text(overrides.inboundKey || inboundIdempotencyKey(message));
  if (!inboundKey) {
    inboundKey = `${text(message.channel || "meta")}:${text(message.external_conversation_id || message.conversation_id || "unknown")}:${Date.now()}`;
    console.log("[meta-send] inboundKey missing fallback used", {
      channel: message.channel || "",
      conversation_id: message.external_conversation_id || message.conversation_id || "",
      inbound_key: inboundKey,
    });
  }
  console.log("[meta-send] inboundKey resolved", {
    channel: message.channel || "",
    conversation_id: message.external_conversation_id || message.conversation_id || "",
    inbound_key: inboundKey,
    inbound_meta_mid: inboundMetaMid,
    source: inboundMetaMid ? "meta_mid" : inboundKey.startsWith("fallback:") ? "computed_fallback" : "explicit_or_timestamp_fallback",
  });
  return { inboundKey, inboundMetaMid };
};

const maskPhoneForDebug = (value = "") => {
  const digits = text(value).replace(/[^\d]/g, "");
  if (!digits) return "";
  return `${"*".repeat(Math.max(0, digits.length - 3))}${digits.slice(-3)}`;
};

const compactMemoryForDebug = (memory = {}) => {
  const preferences = memory?.preferences && typeof memory.preferences === "object" ? memory.preferences : {};
  const activeProductId = text(
    memory.activeProductId ||
    memory.active_product_id ||
    memory.selectedProductId ||
    memory.selected_product_id ||
    preferences.active_product_id ||
    preferences.activeProductId ||
    preferences.selected_product_id ||
    preferences.selectedProductId ||
    preferences.last_product_id ||
    ""
  );
  const lastProductCards = [
    ...(Array.isArray(memory.lastProductCards) ? memory.lastProductCards : []),
    ...(Array.isArray(memory.last_product_cards) ? memory.last_product_cards : []),
    ...(Array.isArray(preferences.lastProductCards) ? preferences.lastProductCards : []),
    ...(Array.isArray(preferences.last_product_cards) ? preferences.last_product_cards : []),
    ...(Array.isArray(memory.last_products) ? memory.last_products : []),
  ];
  return ({
  currentConversationStage: text(memory.currentConversationStage || memory.conversationStage || ""),
  stageReason: text(memory.stageReason || ""),
  nextRecommendedStage: text(memory.nextRecommendedStage || ""),
  buyingStage: text(memory.buyingStage || memory.checkoutStage || preferences.buying_stage || preferences.buyingStage || ""),
  activeTopic: text(memory.activeTopic || ""),
  activeProductId: activeProductId || null,
  active_product_id: activeProductId || null,
  selectedProductId: text(memory.selectedProductId || memory.selected_product_id || preferences.selected_product_id || preferences.selectedProductId || activeProductId) || null,
  last_product_id: text(memory.last_product_id || preferences.last_product_id || activeProductId) || null,
  activeVariantId: memory.activeVariantId || memory.active_variant_id || memory.selectedVariantId || memory.selected_variant_id || preferences.active_variant_id || preferences.selected_variant_id || null,
  activeSize: text(memory.activeSize || memory.active_size || preferences.active_size || preferences.activeSize || ""),
  activeColor: text(memory.activeColor || memory.active_color || memory.selectedColor || memory.selected_color || preferences.active_color || preferences.selected_color || ""),
  activeBrand: text(memory.activeBrand || memory.active_brand || preferences.active_brand || ""),
  activeCategory: text(memory.activeCategory || memory.active_category || preferences.active_category || ""),
  lastIntent: text(memory.lastIntent || memory.last_intent || preferences.lastIntent || preferences.last_intent || ""),
  last_intent: text(memory.last_intent || memory.lastIntent || preferences.last_intent || preferences.lastIntent || ""),
  lastProductCards: lastProductCards.slice(0, 6),
  last_product_cards: lastProductCards.slice(0, 6),
  lastProductCardsCount: lastProductCards.length,
  activeVisualSession: text(memory.activeVisualSession || memory.visualSearchSession?.id || ""),
  lastTopicChangeAt: text(memory.lastTopicChangeAt || ""),
  contextSwitchConfidence: memory.contextSwitchConfidence ?? null,
  switched: memory.switched === true,
  resolvedQuestionType: text(memory.resolvedQuestionType || memory.resolvedQuestion?.intent || ""),
  replyDecisionReason: text(memory.replyDecisionReason || memory.resolvedQuestion?.reason || ""),
  lastReplyCategory: text(memory.lastReplyCategory || ""),
  lastPresentedProductId: text(memory.lastPresentedProductId || ""),
  lastPresentedPrice: text(memory.lastPresentedPrice || ""),
  lastPresentedSizes: Array.isArray(memory.lastPresentedSizes) ? memory.lastPresentedSizes.slice(0, 12) : [],
  lastPresentedColors: Array.isArray(memory.lastPresentedColors) ? memory.lastPresentedColors.slice(0, 12) : [],
  lastPresentationTimestamp: text(memory.lastPresentationTimestamp || ""),
  lastShownProductIds: Array.isArray(memory.lastShownProductIds) ? memory.lastShownProductIds.slice(0, 12) : lastProductCards.map((card) => card?.product_id || card?.id).filter(Boolean).slice(0, 12),
  conversationCompression: Object.fromEntries(
    Object.entries(compressionMemory(memory)).slice(-6).map(([key, value]) => [key, {
      shownPrice: value?.shownPrice === true,
      shownSizes: value?.shownSizes === true,
      shownColors: value?.shownColors === true,
      shownProductCard: value?.shownProductCard === true,
      shownProductLink: value?.shownProductLink === true,
      shownAvailability: value?.shownAvailability === true,
      shownCheckoutPrompt: value?.shownCheckoutPrompt === true,
    }])
  ),
  preferredSizes: Array.isArray(memory.preferredSizes) ? memory.preferredSizes.slice(0, 8) : [],
  preferredBrands: Array.isArray(memory.preferredBrands) ? memory.preferredBrands.slice(0, 12) : [],
  knownName: text(memory.knownName || memory.customerName || ""),
  knownPhone: maskPhoneForDebug(memory.knownPhone || memory.customerPhone || ""),
  lastImageUrl: text(memory.lastImageUrl || ""),
  lastVisualConfidence: memory.lastVisualConfidence ?? memory.lastVisualAttributes?.confidence ?? null,
});
};

const storeAiDebugEvent = async ({ tenantId, channel = "", conversationId = "", event = {} } = {}) => {
  if (!tenantId || !conversationId) return null;
  const metadata = await loadConversationMetadata({ tenantId, channel, conversationId });
  const current = recentMetaArray(metadata, "ai_debug_events");
  const safeEvent = {
    timestamp: nowIso(),
    messageSequenceId: Number.isFinite(Number(event.messageSequenceId || event.message_sequence_id)) ? Number(event.messageSequenceId || event.message_sequence_id) : null,
    message_text: text(event.message_text || "").slice(0, 240),
    classified_intent: text(event.classified_intent || event.intent || ""),
    confidence: Number.isFinite(Number(event.confidence)) ? Number(event.confidence) : null,
    selected_route: text(event.selected_route || event.route || ""),
    memory_changes: event.memory_changes && typeof event.memory_changes === "object" ? event.memory_changes : {},
    reply_preview: text(event.reply_preview || "").slice(0, 260),
    skipped_duplicate: event.skipped_duplicate === true,
    handled_reason: text(event.handled_reason || ""),
    currentConversationStage: text(event.currentConversationStage || event.current_conversation_stage || event.memory_changes?.currentConversationStage || ""),
    stageReason: text(event.stageReason || event.stage_reason || event.memory_changes?.stageReason || ""),
    nextRecommendedStage: text(event.nextRecommendedStage || event.next_recommended_stage || event.memory_changes?.nextRecommendedStage || ""),
    inbound_key: text(event.inbound_key || event.inboundKey || "").slice(0, 180),
    outbound_signature: text(event.outbound_signature || event.outboundSignature || "").slice(0, 180),
    skip_reason: text(event.skip_reason || event.skipReason || ""),
    graph_api_called: event.graph_api_called === true || event.graphApiCalled === true,
    activeTopic: text(event.activeTopic || event.active_topic || event.memory_changes?.activeTopic || ""),
    lastTopicChangeAt: text(event.lastTopicChangeAt || event.last_topic_change_at || event.memory_changes?.lastTopicChangeAt || ""),
    contextSwitchConfidence: Number.isFinite(Number(event.contextSwitchConfidence ?? event.context_switch_confidence))
      ? Number(event.contextSwitchConfidence ?? event.context_switch_confidence)
      : null,
    switched: event.switched === true || event.context_switched === true,
    resolvedQuestionType: text(event.resolvedQuestionType || event.resolved_question_type || event.memory_changes?.resolvedQuestionType || ""),
    replyDecisionReason: text(event.replyDecisionReason || event.reply_decision_reason || event.memory_changes?.replyDecisionReason || ""),
    replyOwner: text(event.replyOwner || event.reply_owner || event.metadata?.replyOwner || event.memory_changes?.replyOwner || ""),
    replySource: text(event.replySource || event.reply_source || event.metadata?.replySource || event.memory_changes?.replySource || ""),
    replyPath: Array.isArray(event.replyPath || event.reply_path)
      ? (event.replyPath || event.reply_path).map(text).filter(Boolean).slice(0, 8)
      : text(event.replyPath || event.reply_path || event.metadata?.replyPath || ""),
  };
  const next = [safeEvent, ...current].slice(0, 20);
  await db.query(
    `
    UPDATE ai_channel_conversations
    SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{ai_debug_events}', $4::jsonb, true),
        updated_at = NOW()
    WHERE tenant_id = $1
      AND external_conversation_id = $2
      AND ($3::text = '' OR channel = $3 OR channel = 'facebook_messenger' OR $3 = 'facebook_messenger')
    `,
    [numberOrNull(tenantId), text(conversationId), text(channel), json(next)]
  ).catch((error) => {
    console.warn("[ai-debug] event store failed", {
      tenant_id: tenantId,
      conversation_id: conversationId,
      message: error?.message || "",
    });
  });
  console.log("[ai-debug] event stored", {
    tenant_id: tenantId,
    conversation_id: conversationId,
    intent: safeEvent.classified_intent,
    route: safeEvent.selected_route,
    skipped_duplicate: safeEvent.skipped_duplicate,
  });
  return next;
};

const storeMetaConversationHealth = async ({ tenantId, channel = "", conversationId = "", patch = {} } = {}) => {
  if (!tenantId || !conversationId || !patch || typeof patch !== "object") return null;
  const metadata = await loadConversationMetadata({ tenantId, channel, conversationId });
  const current = metadata.meta_health && typeof metadata.meta_health === "object" ? metadata.meta_health : {};
  const safePatch = {};
  Object.entries(patch).forEach(([key, value]) => {
    if (value === undefined) return;
    if (key.toLowerCase().includes("token")) {
      safePatch[key] = Boolean(value);
      return;
    }
    safePatch[key] = typeof value === "string" ? value.slice(0, 360) : value;
  });
  const next = { ...current, ...safePatch, updated_at: nowIso() };
  await db.query(
    `
    UPDATE ai_channel_conversations
    SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{meta_health}', $4::jsonb, true),
        updated_at = NOW()
    WHERE tenant_id = $1
      AND external_conversation_id = $2
      AND ($3::text = '' OR channel = $3 OR channel = 'facebook_messenger' OR $3 = 'facebook_messenger')
    `,
    [numberOrNull(tenantId), text(conversationId), text(channel), json(next)]
  ).catch((error) => {
    console.warn("[meta-health] store failed", {
      tenant_id: tenantId,
      conversation_id: conversationId,
      message: error?.message || "",
    });
  });
  console.log("[meta-health] snapshot updated", {
    tenant_id: tenantId,
    conversation_id: conversationId,
    keys: Object.keys(safePatch),
    outbound_status: next.last_outbound_send_status || "",
    dedupe_reason: next.last_dedupe_skip_reason || "",
  });
  return next;
};

const metaOutboundDiagnosticAliases = (patch = {}) => {
  const alias = { ...patch };
  if (patch.last_outbound_send_attempt_at !== undefined) alias.lastOutboundAttemptAt = patch.last_outbound_send_attempt_at;
  if (patch.last_outbound_send_status !== undefined) alias.lastOutboundStatus = patch.last_outbound_send_status;
  if (patch.last_outbound_send_error !== undefined) alias.lastOutboundError = patch.last_outbound_send_error;
  if (patch.last_outbound_meta_code !== undefined) alias.lastMetaSendCode = patch.last_outbound_meta_code;
  if (patch.last_outbound_recipient_preview !== undefined) alias.recipientIdPreview = patch.last_outbound_recipient_preview;
  if (patch.last_outbound_page_id !== undefined) alias.pageId = patch.last_outbound_page_id;
  if (patch.last_outbound_token_present !== undefined) alias.tokenPresent = patch.last_outbound_token_present === true;
  if (patch.last_outbound_decision !== undefined) alias.lastOutboundDecision = patch.last_outbound_decision;
  if (patch.last_outbound_skip_reason !== undefined) alias.lastOutboundSkipReason = patch.last_outbound_skip_reason;
  if (patch.last_inbound_mid !== undefined) alias.lastInboundMid = patch.last_inbound_mid;
  if (patch.last_processed_inbound_key !== undefined) alias.lastProcessedInboundKey = patch.last_processed_inbound_key;
  if (patch.last_reply_signature !== undefined) alias.lastReplySignature = patch.last_reply_signature;
  return alias;
};

const storeMetaOutboundDiagnostics = async ({ tenantId, channel = "", conversationId = "", patch = {}, error = null } = {}) => {
  const next = await storeMetaConversationHealth({ tenantId, channel, conversationId, patch: metaOutboundDiagnosticAliases(patch) }).catch(() => null);
  const errorPayload = error ? metaSendErrorPayload(error) : null;
  const topLevelError = errorPayload || (patch.last_outbound_send_error ? {
    message: patch.last_outbound_send_error,
    code: patch.last_outbound_meta_code || "",
    status: patch.last_outbound_meta_status || null,
  } : null);
  if (topLevelError) {
    await db.query(
      `
      UPDATE ai_channel_conversations
      SET metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{ai_last_outbound_error}', $4::jsonb, true),
          updated_at = NOW()
      WHERE tenant_id = $1
        AND external_conversation_id = $2
        AND ($3::text = '' OR channel = $3 OR channel = 'facebook_messenger' OR $3 = 'facebook_messenger')
      `,
      [numberOrNull(tenantId), text(conversationId), text(channel), json(topLevelError)]
    ).catch((storeError) => {
      console.warn("[meta-send] failed to store ai_last_outbound_error", {
        tenant_id: tenantId,
        conversation_id: conversationId,
        message: storeError?.message || "",
      });
    });
  }
  return next;
};

export const getAiInboxConversationDebug = async ({ tenantId, channel = "", conversationId = "" } = {}) => {
  if (!tenantId || !conversationId) {
    throw Object.assign(new Error("tenant_id and conversation_id are required"), { status: 400 });
  }
  const metadata = await loadConversationMetadata({ tenantId, channel, conversationId });
  const channelMemory = metadata.ai_memory && typeof metadata.ai_memory === "object" ? metadata.ai_memory : {};
  const persistentMemory = await loadAiConversationMemory({
    tenantId,
    sessionId: conversationId,
    customerPhone: metadata.customer_phone || metadata.external_customer_id || "",
  }).catch(() => null);
  const memory = {
    ...channelMemory,
    ...(persistentMemory || {}),
    preferences: {
      ...(channelMemory.preferences || {}),
      ...(persistentMemory?.preferences || {}),
    },
  };
  const health = metadata.meta_health && typeof metadata.meta_health === "object" ? metadata.meta_health : {};
  const debugEvents = recentMetaArray(metadata, "ai_debug_events").slice(0, 20);
  const inboundKeys = recentMetaArray(metadata, "ai_processed_inbound_keys");
  const outboundSignatures = recentMetaArray(metadata, "ai_recent_outbound_signatures");
  const latestOutboundSignature = outboundSignatures[outboundSignatures.length - 1] || {};
  const latestEvent = debugEvents[0] || {};
  const compactMemory = compactMemoryForDebug(memory);
  const memoryHasProductContext = Boolean(compactMemory.activeProductId || compactMemory.lastProductCardsCount);
  const projectedIntent = memoryHasProductContext
    ? text(compactMemory.last_intent || compactMemory.lastIntent || latestEvent.classified_intent || "")
    : text(latestEvent.classified_intent || compactMemory.last_intent || compactMemory.lastIntent || "");
  const data = {
    conversation_id: conversationId,
    current_intent: projectedIntent,
    confidence: latestEvent.confidence ?? null,
    route: text(latestEvent.selected_route || latestEvent.handled_reason || ""),
    memory: compactMemory,
    processed_inbound_key_count: inboundKeys.length,
    unified_reply_preview: text(latestOutboundSignature?.preview || latestEvent.reply_preview || latestEvent.reply || ""),
    last_outbound_signature_preview: text(latestOutboundSignature?.preview || latestOutboundSignature?.signature || ""),
    lastOutboundAttemptAt: health.lastOutboundAttemptAt || health.last_outbound_send_attempt_at || null,
    lastOutboundStatus: health.lastOutboundStatus || health.last_outbound_send_status || "",
    lastOutboundError: health.lastOutboundError || health.last_outbound_send_error || "",
    lastMetaSendCode: health.lastMetaSendCode || health.last_outbound_meta_code || "",
    recipientIdPreview: health.recipientIdPreview || health.last_outbound_recipient_preview || "",
    pageId: health.pageId || health.last_outbound_page_id || "",
    tokenPresent: health.tokenPresent === true || health.last_outbound_token_present === true,
    lastOutboundDecision: health.lastOutboundDecision || health.last_outbound_decision || health.lastOutboundStatus || health.last_outbound_send_status || "",
    lastOutboundSkipReason: health.lastOutboundSkipReason || health.last_outbound_skip_reason || health.last_dedupe_skip_reason || "",
    lastInboundMid: health.lastInboundMid || health.last_inbound_mid || health.last_inbound_meta_mid || "",
    lastProcessedInboundKey: health.lastProcessedInboundKey || health.last_processed_inbound_key || "",
    lastReplySignature: health.lastReplySignature || health.last_reply_signature || "",
    debug_events: debugEvents,
  };
  console.log("[ai-debug] panel data loaded", {
    tenant_id: tenantId,
    conversation_id: conversationId,
    event_count: debugEvents.length,
    current_intent: data.current_intent,
  });
  return data;
};

