const parseMetaDate = (value = null) => {
  if (!value) return null;
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  const safe = text(value);
  if (!safe) return null;
  const direct = new Date(safe);
  if (!Number.isNaN(direct.getTime())) return direct;
  const match = safe.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[,\s]+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?)?$/i);
  if (!match) return null;
  const [, first, second, year, hour = "0", minute = "0", secondPart = "0", meridiem = ""] = match;
  const month = Number(first);
  const day = Number(second);
  let hours = Number(hour);
  if (/pm/i.test(meridiem) && hours < 12) hours += 12;
  if (/am/i.test(meridiem) && hours === 12) hours = 0;
  const parsed = new Date(Number(year), month - 1, day, hours, Number(minute), Number(secondPart));
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};

const channelAlias = (channel = "") => (channel === AI_AGENT_CHANNELS.INSTAGRAM ? "instagram" : "facebook");

const isMetaAutoReplyChannel = (channel = "") => {
  const normalized = text(channel).toLowerCase();
  return normalized.includes("instagram") || normalized.includes("facebook") || normalized.includes("messenger");
};

const metaAutoReplyPauseChannelLabel = (channel = "") => {
  const normalized = text(channel).toLowerCase();
  return normalized.includes("instagram") ? "instagram" : "messenger";
};
const adapterChannel = (channel = "") => (channel === "instagram" ? AI_AGENT_CHANNELS.INSTAGRAM : AI_AGENT_CHANNELS.FACEBOOK_MESSENGER);
const normalizeMetaAccountId = (value = "") => text(value).replace(/[^\d]/g, "");
const summarizeMetaWebhookPayload = (payload = {}) => {
  const entries = Array.isArray(payload.entry) ? payload.entry : [];
  const changeFields = [];
  const itemTypes = [];
  const verbValues = [];
  for (const entry of entries) {
    for (const change of Array.isArray(entry?.changes) ? entry.changes : []) {
      changeFields.push(text(change?.field || "").toLowerCase());
      itemTypes.push(text(change?.value?.item || "").toLowerCase());
      verbValues.push(text(change?.value?.verb || "").toLowerCase());
    }
  }
  return {
    object: text(payload.object || "").toLowerCase(),
    entry_count: entries.length,
    change_fields: [...new Set(changeFields)].filter(Boolean),
    item_types: [...new Set(itemTypes)].filter(Boolean),
    verb_values: [...new Set(verbValues)].filter(Boolean),
  };
};

