const getPageTasks = async ({ pageId = "", token = "" } = {}) => {
  const safePageId = text(pageId);
  const safeToken = text(token);
  if (!safePageId || !safeToken) return [];
  try {
    const payload = await callMetaGet({
      endpoint: `/${encodeURIComponent(safePageId)}`,
      token: safeToken,
      params: { fields: "id,name,tasks" },
    });
    const tasks = Array.isArray(payload?.tasks) ? payload.tasks : [];
    return [...new Set(tasks.map(text).filter(Boolean))];
  } catch (error) {
    console.warn("[meta-permissions] page_tasks_fetch_failed", {
      page_id: maskIdForLog(safePageId),
      message: error?.message || "Unable to fetch page tasks",
    });
    return [];
  }
};

const buildMissingItems = (items = []) => items.filter((item) => !item.done).map((item) => item.label);

const hasPageTokenAndPage = (config = {}) => Boolean(config.page_access_token_configured && config.facebook_page_id);
const hasInstagramBase = (config = {}) => Boolean(hasPageTokenAndPage(config) && config.instagram_business_account_id);

const buildMetaChannels = (config = {}, setupCompletion = null) => {
  const tokenValid = Boolean(config.page_access_token_configured && !tokenExpired(config));
  const webhookOperational = Boolean(
    setupCompletion?.webhook_verified &&
      setupCompletion?.webhook_enabled &&
      setupCompletion?.subscribed_apps_verified
  );
  const messengerOperational = Boolean(tokenValid && hasPageTokenAndPage(config) && webhookOperational);
  const instagramOperational = Boolean(tokenValid && hasInstagramBase(config) && webhookOperational);
  const messengerConnected = Boolean((config.messenger_enabled && hasPageTokenAndPage(config) && capabilityOk(config, "facebook_messenger")) || messengerOperational);
  const facebookPublishingConnected = Boolean(config.facebook_publishing_enabled && hasPageTokenAndPage(config) && capabilityOk(config, "facebook_publishing"));
  const instagramDmConnected = Boolean((config.instagram_dm_enabled && hasInstagramBase(config) && capabilityOk(config, "instagram_dm")) || instagramOperational);
  const instagramPublishingConnected = Boolean(config.instagram_publishing_enabled && hasInstagramBase(config) && capabilityOk(config, "instagram_publishing"));
  return {
    facebook: {
      connected: messengerConnected || facebookPublishingConnected,
      messenger_connected: messengerConnected,
      webhook_healthy: webhookOperational,
      token_valid: tokenValid,
      messaging_active: messengerConnected,
      operational_source: messengerOperational ? "webhook_verified" : "capability_status",
      publishing_connected: facebookPublishingConnected,
      messenger_enabled: config.messenger_enabled,
      publishing_enabled: config.facebook_publishing_enabled,
      page_id: config.facebook_page_id,
      page_name: config.facebook_page_name || config.page_name || "",
      last_sync_at: config.last_sync_at,
      token_expires_at: config.token_expires_at,
      missing: {
        messenger: buildMissingItems([
          { done: config.page_access_token_configured, label: "page_access_token" },
          { done: Boolean(config.facebook_page_id), label: "facebook_page_id" },
          { done: capabilityOk(config, "facebook_messenger") || messengerOperational, label: "messenger_permission_test" },
        ]),
        publishing: buildMissingItems([
          { done: config.page_access_token_configured, label: "page_access_token" },
          { done: Boolean(config.facebook_page_id), label: "facebook_page_id" },
          { done: capabilityOk(config, "facebook_publishing"), label: "publish_permission_test" },
        ]),
      },
    },
    instagram: {
      connected: instagramDmConnected || instagramPublishingConnected,
      dm_connected: instagramDmConnected,
      webhook_healthy: webhookOperational,
      token_valid: tokenValid,
      messaging_active: instagramDmConnected,
      operational_source: instagramOperational ? "webhook_verified" : "capability_status",
      publishing_connected: instagramPublishingConnected,
      dm_enabled: config.instagram_dm_enabled,
      publishing_enabled: config.instagram_publishing_enabled,
      business_account_id: config.instagram_business_account_id,
      username: config.instagram_username,
      last_sync_at: config.last_sync_at,
      token_expires_at: config.token_expires_at,
      missing: {
        dm: buildMissingItems([
          { done: config.page_access_token_configured, label: "page_access_token" },
          { done: Boolean(config.instagram_business_account_id), label: "instagram_business_account_id" },
          { done: capabilityOk(config, "instagram_dm") || instagramOperational, label: "instagram_messaging_permission_test" },
        ]),
        publishing: buildMissingItems([
          { done: config.page_access_token_configured, label: "page_access_token" },
          { done: Boolean(config.instagram_business_account_id), label: "instagram_business_account_id" },
          { done: capabilityOk(config, "instagram_publishing"), label: "instagram_content_publish_test" },
        ]),
      },
    },
  };
};

export const getMetaIntegrationStatus = async ({ tenantId, req = null } = {}) => {
  await repairMetaConfigFromMarketingSettings({ tenantId }).catch((error) => {
    console.warn("[meta-status] marketing_settings repair failed", {
      tenant_id: numberOrNull(tenantId),
      message: error?.message || "unknown",
    });
  });
  const row = await getMetaIntegrationConfig({ tenantId });
  const config = row ? sanitizeConfig(row) : defaultPublicConfig(tenantId);
  const webhookUrl = `${backendOriginFor(req)}/api/meta/webhook`;
  if (config.facebook_page_id) {
    await repairDuplicateMetaConfigsForPage({ facebookPageId: config.facebook_page_id }).catch((error) => {
      console.warn("[meta-status] duplicate safety repair failed", {
        tenant_id: numberOrNull(tenantId),
        facebook_page_id: maskIdForLog(config.facebook_page_id),
        message: error?.message || "unknown",
      });
    });
  }
  const webhookSubscription = {
    ...(config.capability_status?.webhook?.subscribed_apps || {}),
    webhook_enabled: config.webhook_enabled || config.capability_status?.webhook?.subscribed_apps?.webhook_enabled,
    webhook_verified: config.webhook_verified || config.capability_status?.webhook?.subscribed_apps?.webhook_verified,
    subscribed_apps_verified: config.subscribed_apps_verified || config.capability_status?.webhook?.subscribed_apps?.subscribed_apps_verified,
  };
  const setupCompletion = evaluateMetaSetupCompletion({ config, webhookSubscription });
  const subscribedAppsOk = setupCompletion.subscribed_apps_verified;
  const webhookVerified = setupCompletion.webhook_verified;
  console.log("[meta-status] meta_status_token_check", {
    tenant_id: numberOrNull(tenantId),
    config_id: config.id || null,
    token_saved: config.page_access_token_configured,
    token_expires_at: config.token_expires_at,
    token_expires_in_seconds: secondsUntil(config.token_expires_at),
    token_expired: tokenExpired(config),
    token_status: config.token_status,
    overall_status: setupCompletion.complete ? META_FULLY_CONNECTED_STATUS : config.status,
  });
  console.log("[meta-status] meta_status_permission_check", {
    tenant_id: numberOrNull(tenantId),
    config_id: config.id || null,
    permissions_saved: setupCompletion.permissions_saved,
    messenger_enabled: config.messenger_enabled,
    instagram_dm_enabled: config.instagram_dm_enabled,
    capability_keys: Object.keys(config.capability_status || {}),
  });
  console.log("[meta-status] meta_status_webhook_flags", {
    tenant_id: numberOrNull(tenantId),
    config_id: config.id || null,
    webhook_enabled: setupCompletion.webhook_enabled,
    webhook_verified: setupCompletion.webhook_verified,
    subscribed_apps_verified: setupCompletion.subscribed_apps_verified,
    physical_webhook_enabled: config.webhook_enabled,
    physical_webhook_verified: config.webhook_verified,
    physical_subscribed_apps_verified: config.subscribed_apps_verified,
  });
  return {
    config,
    webhook_url: webhookUrl,
    subscribed_apps: webhookSubscription,
    overall_status: setupCompletion.complete ? META_FULLY_CONNECTED_STATUS : config.status,
    setup_completion: setupCompletion,
    checklist: {
      meta_app_created: Boolean(config.app_id),
      page_connected: Boolean(config.facebook_page_id && config.page_access_token_configured),
      instagram_professional_linked: Boolean(config.instagram_business_account_id),
      webhook_verified: webhookVerified,
      webhook_enabled: setupCompletion.webhook_enabled,
      subscribed_apps: subscribedAppsOk,
      token_saved: config.page_access_token_configured,
    },
    channels: buildMetaChannels(config, setupCompletion),
  };
};

const latestValue = (rows = [], key = "created_at") => rows[0]?.[key] || null;

const safeDb = async (query, params = [], fallback = { rows: [] }) => {
  try {
    return await db.query(query, params);
  } catch (error) {
    if (["42P01", "42703"].includes(error?.code)) return fallback;
    throw error;
  }
};

export const getMetaWebhookHealth = async ({ tenantId, req = null } = {}) => {
  const scopedTenantId = numberOrNull(tenantId);
  const status = await getMetaIntegrationStatus({ tenantId: scopedTenantId, req });
  const [events, messages, posts, commentLogs] = await Promise.all([
    safeDb(
      `
      SELECT created_at, status, error, message_preview
      FROM ai_channel_event_logs
      WHERE tenant_id = $1
        AND channel IN ('facebook_messenger','instagram')
      ORDER BY created_at DESC
      LIMIT 100
      `,
      [scopedTenantId]
    ),
    safeDb(
      `
      SELECT created_at, message_text, channel
      FROM ai_support_messages
      WHERE tenant_id = $1
        AND channel IN ('facebook','instagram','facebook_messenger')
        AND sender_type = 'customer'
      ORDER BY created_at DESC
      LIMIT 20
      `,
      [scopedTenantId]
    ),
    safeDb(
      `
      SELECT published_at, updated_at, status, error_message
      FROM marketing_posts
      WHERE tenant_id = $1
        AND (published_at IS NOT NULL OR status = 'failed')
      ORDER BY COALESCE(published_at, updated_at, created_at) DESC
      LIMIT 100
      `,
      [scopedTenantId]
    ),
    safeDb(
      `
      SELECT created_at, updated_at, status, error_message
      FROM marketing_comment_dm_logs
      WHERE tenant_id = $1
      ORDER BY created_at DESC
      LIMIT 100
      `,
      [scopedTenantId]
    ),
  ]);
  const failedEvents = events.rows.filter((event) => ["failed", "error"].includes(text(event.status).toLowerCase()) || event.error);
  const failedCommentLogs = commentLogs.rows.filter((log) => text(log.status).toLowerCase() === "failed" || log.error_message);
  const successfulPost = posts.rows.find((post) => text(post.status).toLowerCase() === "published" || post.published_at) || null;
  const failedPostCount = posts.rows.filter((post) => text(post.status).toLowerCase() === "failed" || post.error_message).length;
  const lastRetry = [...failedEvents, ...failedCommentLogs].sort((a, b) => new Date(b.updated_at || b.created_at) - new Date(a.updated_at || a.created_at))[0] || null;
  return {
    webhook_url: status.webhook_url,
    subscribed_apps: status.subscribed_apps || {},
    setup_completion: status.setup_completion || {},
    subscribed_apps_status: status.subscribed_apps?.subscribed_apps_status || "unknown",
    webhook_subscription_status: status.subscribed_apps?.webhook_subscription_status || "unknown",
    webhook_verification_status: status.subscribed_apps?.webhook_verification_status || (status.checklist?.webhook_verified ? "verified" : "unverified"),
    webhook_verified: Boolean(status.checklist?.webhook_verified),
    webhook_enabled: Boolean(status.config?.webhook_enabled),
    last_webhook_event: latestValue(events.rows),
    last_incoming_message: latestValue(messages.rows),
    last_successful_publish: successfulPost?.published_at || successfulPost?.updated_at || null,
    failed_webhook_deliveries: failedEvents.length + failedCommentLogs.length,
    failed_publishes: failedPostCount,
    last_retry: lastRetry?.updated_at || lastRetry?.created_at || null,
    event_throughput_24h: events.rows.filter((event) => new Date(event.created_at).getTime() >= Date.now() - 86400000).length,
    recent_events: events.rows.slice(0, 10),
  };
};

export const getMetaWebhookDebugStatus = async ({ tenantId, req = null } = {}) => {
  const scopedTenantId = numberOrNull(tenantId);
  const [integrationStatus, commentWebhookStatus, socialCommentEvents, marketingCommentEvents, webhookRequestsLast24h, commentEventsLast24h] = await Promise.all([
    getMetaIntegrationStatus({ tenantId: scopedTenantId, req }),
    getMarketingCommentWebhookStatus(scopedTenantId),
    safeDb(
      `
      SELECT created_at
      FROM social_comment_automation_runs
      WHERE tenant_id = $1
      ORDER BY created_at DESC, id DESC
      LIMIT 1
      `,
      [scopedTenantId]
    ),
    safeDb(
      `
      SELECT created_at, processed_at
      FROM marketing_comment_events
      WHERE business_id = $1::bigint
      ORDER BY COALESCE(processed_at, created_at) DESC, id DESC
      LIMIT 1
      `,
      [scopedTenantId]
    ),
    countMarketingWebhookRequestsLast24h(scopedTenantId).catch(() => 0),
    countMarketingCommentEventsLast24h(scopedTenantId).catch(() => 0),
  ]);

  const config = integrationStatus?.config || {};
  const subscribedFields = Array.from(
    new Set([
      ...(Array.isArray(integrationStatus?.subscribed_apps?.subscribed_fields) ? integrationStatus.subscribed_apps.subscribed_fields : []),
      ...(Array.isArray(integrationStatus?.setup_completion?.subscribed_fields) ? integrationStatus.setup_completion.subscribed_fields : []),
      ...(Array.isArray(commentWebhookStatus?.subscribed_fields) ? commentWebhookStatus.subscribed_fields : []),
    ])
  ).filter(Boolean);
  const lastCommentEventAt = socialCommentEvents.rows[0]?.created_at || marketingCommentEvents.rows[0]?.processed_at || marketingCommentEvents.rows[0]?.created_at || null;
  const lastCommentSavedAt = marketingCommentEvents.rows[0]?.processed_at || marketingCommentEvents.rows[0]?.created_at || null;

  return {
    tenant_id: scopedTenantId,
    facebook_page_id: config.facebook_page_id || "",
    instagram_business_account_id: config.instagram_business_account_id || "",
    verify_token_configured: Boolean(config.verify_token_configured),
    verify_token_masked: config.verify_token_masked || "",
    primary_webhook_url: getMetaWebhookUrl(),
    alternate_webhook_url: commentWebhookStatus?.webhook_url || integrationStatus?.webhook_url || "",
    webhook_url: commentWebhookStatus?.webhook_url || integrationStatus?.webhook_url || "",
    subscribed_fields: subscribedFields,
    last_comment_event_at: lastCommentEventAt,
    last_comment_saved_at: lastCommentSavedAt,
    webhook_requests_last_24h: Number(webhookRequestsLast24h || 0),
    comment_events_last_24h: Number(commentEventsLast24h || 0),
    comments_delivery_mode: commentWebhookStatus?.comments_delivery_mode || (subscribedFields.includes("feed") ? "facebook_feed" : "webhook"),
    comments_delivery_ready: Boolean(commentWebhookStatus?.comments_delivery_ready ?? subscribedFields.includes("feed")),
    comment_webhook_status: commentWebhookStatus || {},
    meta_integration_status: {
      overall_status: integrationStatus?.overall_status || "",
      subscribed_apps: integrationStatus?.subscribed_apps || {},
      setup_completion: integrationStatus?.setup_completion || {},
      checklist: integrationStatus?.checklist || {},
    },
  };
};

export const getMetaWebhookSubscriptionDebugStatus = async ({ tenantId, req = null } = {}) => {
  const scopedTenantId = numberOrNull(tenantId);
  const config = await getMetaIntegrationConfig({ tenantId: scopedTenantId });
  const pageId = text(config?.facebook_page_id || config?.page_id || "");
  let tokenPresent = false;
  let tokenError = "";
  let resolvedToken = "";
  let subscription = null;
  if (config) {
    try {
      resolvedToken = getTokenForConfig(config);
      tokenPresent = Boolean(resolvedToken);
    } catch (error) {
      tokenError = error?.message || "Unable to resolve Meta page token";
    }
    if (tokenPresent) {
      subscription = await getPageSubscribedApps({ pageId, token: resolvedToken });
    }
  }
  const subscribedFields = Array.isArray(subscription?.subscribed_fields) ? subscription.subscribed_fields : [];
  const feedSubscribed = subscribedFields.includes("feed");
  const requestedFields = [...META_WEBHOOK_SUBSCRIBED_FIELDS, ...META_WEBHOOK_COMMENT_FIELDS];
  const acceptedCommentFields = subscribedFields.filter((field) => META_WEBHOOK_COMMENT_FIELDS.includes(field));
  const missingOptionalFields = META_WEBHOOK_COMMENT_FIELDS.filter((field) => !subscribedFields.includes(field));
  return {
    tenant_id: scopedTenantId,
    page_id: pageId,
    callback_url: getMetaWebhookUrl(),
    configured_webhook_url: getMetaWebhookUrl(),
    requested_fields: requestedFields,
    accepted_subscribed_fields: subscribedFields,
    accepted_comment_fields: acceptedCommentFields,
    missing_optional_fields: missingOptionalFields,
    token_present: tokenPresent,
    token_error: tokenError || "",
    subscribed_fields: subscribedFields,
    feed_subscribed: feedSubscribed,
    feed_alone_should_be_enough_for_comments: true,
    page_subscription_present: Boolean(subscription?.page_subscription_present),
    app_installed: Boolean(subscription?.app_installed),
    errors: [
      ...(tokenError ? [tokenError] : []),
      ...(subscription?.error ? [subscription.error] : []),
    ],
    subscription: subscription || {},
    meta_integration_status: config || {},
  };
};

export const getMetaPermissionsDebugStatus = async ({ tenantId, req = null } = {}) => {
  const scopedTenantId = numberOrNull(tenantId);
  const row = await getMetaIntegrationConfig({ tenantId: scopedTenantId });
  const config = row ? sanitizeConfig(row) : defaultPublicConfig(scopedTenantId);
  const token = row ? getTokenForConfig(row) : "";
  const permissions = await getGrantedPermissions({ token });
  const pageId = text(config.facebook_page_id || config.page_id);
  const pageTasks = await getPageTasks({ pageId, token });
  const granted = Array.isArray(permissions.granted) ? permissions.granted : [];
  const declined = Array.isArray(permissions.declined) ? permissions.declined : [];
  const allScopes = Array.isArray(permissions.all_scopes) ? permissions.all_scopes : granted;
  return {
    tenant_id: scopedTenantId,
    granted_permissions: granted,
    declined_permissions: declined,
    page_tasks: pageTasks,
    page_access_token_scopes: allScopes,
  };
};

const summarizeSocialCommentPrivateReplyRawPayload = (payload = {}) => {
  const safePayload = payload && typeof payload === "object" ? payload : {};
  const value = safePayload.value && typeof safePayload.value === "object" ? safePayload.value : {};
  const comment = safePayload.comment && typeof safePayload.comment === "object" ? safePayload.comment : {};
  const from = value.from && typeof value.from === "object" ? value.from : safePayload.from && typeof safePayload.from === "object" ? safePayload.from : {};
  return {
    source: text(safePayload.source || ""),
    keys: Object.keys(safePayload),
    value_keys: Object.keys(value),
    comment_keys: Object.keys(comment),
    from_keys: Object.keys(from),
    value_comment_id: text(value.comment_id || safePayload.comment_id || ""),
    value_post_id: text(value.post_id || safePayload.post_id || ""),
    value_parent_id: text(value.parent_id || safePayload.parent_id || ""),
    value_message_id: text(value.message_id || safePayload.message_id || ""),
    value_from_id: text(value.from?.id || safePayload.from?.id || value.from?.user_id || safePayload.from?.user_id || ""),
    value_from_name: text(value.from?.name || safePayload.from?.name || value.from?.full_name || safePayload.from?.full_name || ""),
  };
};

export const getMetaCommentPrivateReplyCapabilityDebug = async ({ tenantId = null, commentId = "" } = {}) => {
  await ensureMetaIntegrationSchema();
  const scopedTenantId = numberOrNull(tenantId);
  const safeCommentId = text(commentId);
  if (!scopedTenantId || !safeCommentId) {
    throw Object.assign(new Error("tenant_id and comment_id are required"), { status: 400 });
  }

  const row = await getMetaIntegrationConfig({ tenantId: scopedTenantId });
  const config = row ? sanitizeConfig(row) : defaultPublicConfig(scopedTenantId);
  const token = row ? getTokenForConfig(row) : "";

  const [webhookStatus, permissionsStatus, socialRunRows, messageRows] = await Promise.all([
    getMetaWebhookDebugStatus({ tenantId: scopedTenantId }).catch(() => null),
    getMetaPermissionsDebugStatus({ tenantId: scopedTenantId }).catch(() => null),
    db.query(
      `
      SELECT id, platform, channel, post_id, comment_id, commenter_id, commenter_name, inbox_conversation_id, raw_payload, created_at, updated_at
      FROM social_comment_automation_runs
      WHERE tenant_id = $1::bigint
        AND (
          comment_id = $2::text
          OR inbox_conversation_id = $2::text
          OR COALESCE(raw_payload->>'comment_id', '') = $2::text
          OR COALESCE(raw_payload->'value'->>'comment_id', '') = $2::text
        )
      ORDER BY
        CASE
          WHEN COALESCE(raw_payload->>'source', '') = 'meta_webhook' THEN 0
          WHEN COALESCE(raw_payload->>'source', '') = 'meta_comment_poll' THEN 1
          ELSE 2
        END,
        created_at DESC,
        id DESC
      LIMIT 20
      `,
      [scopedTenantId, safeCommentId]
    ).catch(() => ({ rows: [] })),
    db.query(
      `
      SELECT id, session_id, comment_id, external_message_id, provider_message_id, channel, raw_payload, created_at, updated_at
      FROM ai_support_messages
      WHERE tenant_id = $1::bigint
        AND (
          comment_id = $2::text
          OR external_message_id = $2::text
          OR provider_message_id = $2::text
          OR session_id = $2::text
          OR COALESCE(raw_payload->>'comment_id', '') = $2::text
          OR COALESCE(raw_payload->'value'->>'comment_id', '') = $2::text
        )
      ORDER BY created_at DESC, id DESC
      LIMIT 20
      `,
      [scopedTenantId, safeCommentId]
    ).catch(() => ({ rows: [] })),
  ]);

  let commentProbe = null;
  let commentProbeSuccess = false;
  let commentProbeError = "";
  let canReplyPrivately = null;
  let canReplyPrivatelyError = "";
  if (token) {
    try {
      commentProbe = await callMetaGet({
        endpoint: `/${encodeURIComponent(safeCommentId)}`,
        token,
        params: { fields: "id,message,from,parent,permalink_url,created_time" },
      });
      commentProbeSuccess = true;
    } catch (error) {
      commentProbeError = error?.message || "";
    }

    try {
      const canReplyPayload = await callMetaGet({
        endpoint: `/${encodeURIComponent(safeCommentId)}`,
        token,
        params: { fields: "can_reply_privately" },
      });
      canReplyPrivately = typeof canReplyPayload?.can_reply_privately === "boolean" ? canReplyPayload.can_reply_privately : null;
    } catch (error) {
      canReplyPrivatelyError = error?.message || "";
    }
  }

  const webhookSubscribedFields = Array.isArray(webhookStatus?.subscribed_fields)
    ? webhookStatus.subscribed_fields
    : Array.isArray(webhookStatus?.subscribed_apps?.subscribed_fields)
      ? webhookStatus.subscribed_apps.subscribed_fields
      : Array.isArray(webhookStatus?.setup_completion?.subscribed_fields)
        ? webhookStatus.setup_completion.subscribed_fields
        : [];
  const permissionsPayload = permissionsStatus || {};
  const normalizeFlowRow = (row = {}, rowType = "") => {
    const rawPayload = row.raw_payload && typeof row.raw_payload === "object" ? row.raw_payload : {};
    const value = rawPayload.value && typeof rawPayload.value === "object" ? rawPayload.value : {};
    const comment = rawPayload.comment && typeof rawPayload.comment === "object" ? rawPayload.comment : {};
    const from = value.from && typeof value.from === "object" ? value.from : rawPayload.from && typeof rawPayload.from === "object" ? rawPayload.from : {};
    return {
      row_type: rowType,
      id: row.id || null,
      source: text(rawPayload.source || ""),
      origin: text(rawPayload.source || "").includes("webhook") ? "webhook" : text(rawPayload.source || "").includes("poll") ? "poller" : "unknown",
      comment_id: text(row.comment_id || ""),
      post_id: text(row.post_id || ""),
      commenter_id: text(row.commenter_id || ""),
      commenter_name: text(row.commenter_name || ""),
      session_id: text(row.session_id || row.inbox_conversation_id || ""),
      raw_payload_shape: summarizeSocialCommentPrivateReplyRawPayload({
        ...rawPayload,
        value,
        comment,
        from,
      }),
      created_at: row.created_at || null,
      updated_at: row.updated_at || null,
    };
  };
  const runRows = (socialRunRows.rows || []).map((row) => normalizeFlowRow(row, "social_comment_automation_runs"));
  const messageRowsNormalized = (messageRows.rows || []).map((row) => normalizeFlowRow(row, "ai_support_messages"));

  console.log("[social-comments:private-reply-capability-debug]", {
    tenant_id: scopedTenantId,
    comment_id: safeCommentId,
    page_id: text(config.facebook_page_id || config.page_id || ""),
    permissions_saved: Boolean(config.permissions_saved),
    webhook_enabled: Boolean(config.webhook_enabled),
    webhook_verified: Boolean(config.webhook_verified),
    subscribed_fields: webhookSubscribedFields,
    can_reply_privately: canReplyPrivately,
    can_reply_privately_error: canReplyPrivatelyError,
    comment_probe_success: commentProbeSuccess,
    comment_probe_error: commentProbeError,
    comment_probe: commentProbe,
    webhook_context_rows: runRows.filter((row) => row.origin === "webhook"),
    poller_context_rows: runRows.filter((row) => row.origin === "poller"),
    message_context_rows: messageRowsNormalized,
    token_present: Boolean(token),
    permissions_granted: Array.isArray(permissionsPayload.granted_permissions) ? permissionsPayload.granted_permissions : [],
    permissions_declined: Array.isArray(permissionsPayload.declined_permissions) ? permissionsPayload.declined_permissions : [],
    page_tasks: Array.isArray(permissionsPayload.page_tasks) ? permissionsPayload.page_tasks : [],
  });

  return {
    tenant_id: scopedTenantId,
    comment_id: safeCommentId,
    page_id: text(config.facebook_page_id || config.page_id || ""),
    permissions_saved: Boolean(config.permissions_saved),
    webhook: {
      subscribed_fields: webhookSubscribedFields,
      comments_delivery_mode: webhookStatus?.comments_delivery_mode || "",
      comments_delivery_ready: Boolean(webhookStatus?.comments_delivery_ready),
      webhook_verified: Boolean(webhookStatus?.webhook_verified),
      webhook_enabled: Boolean(webhookStatus?.webhook_enabled),
      subscribed_apps_status: webhookStatus?.subscribed_apps_status || "",
      webhook_subscription_status: webhookStatus?.webhook_subscription_status || "",
    },
    permissions: {
      granted_permissions: Array.isArray(permissionsPayload.granted_permissions) ? permissionsPayload.granted_permissions : [],
      declined_permissions: Array.isArray(permissionsPayload.declined_permissions) ? permissionsPayload.declined_permissions : [],
      page_tasks: Array.isArray(permissionsPayload.page_tasks) ? permissionsPayload.page_tasks : [],
      page_access_token_present: Boolean(config.page_access_token_configured),
    },
    comment_probe: {
      success: commentProbeSuccess,
      error: commentProbeError,
      raw: commentProbe || null,
      can_reply_privately: canReplyPrivately,
      can_reply_privately_error: canReplyPrivatelyError,
    },
    source_rows: {
      social_comment_automation_runs: runRows,
      ai_support_messages: messageRowsNormalized,
    },
    likely_supported: Boolean(commentProbeSuccess && (canReplyPrivately === true || canReplyPrivately === null)),
  };
};

export const getMetaPostCommentsDebugStatus = async ({ tenantId, postId = "" } = {}) => {
  const scopedTenantId = numberOrNull(tenantId);
  const safePostId = text(postId);
  if (!safePostId) {
    return {
      success: false,
      post_id: "",
      comments_count: 0,
      comments_sample: [],
      graph_error: "post_id is required",
    };
  }

  const row = await getMetaIntegrationConfig({ tenantId: scopedTenantId });
  const token = row ? getTokenForConfig(row) : "";
  if (!token) {
    return {
      success: false,
      post_id: safePostId,
      comments_count: 0,
      comments_sample: [],
      graph_error: "Page access token is missing",
    };
  }

  try {
    const payload = await callMetaGet({
      endpoint: `/${encodeURIComponent(safePostId)}/comments`,
      token,
      params: { fields: "id,message,from,created_time,parent" },
    });
    const comments = Array.isArray(payload?.data) ? payload.data : [];
    return {
      success: true,
      post_id: safePostId,
      comments_count: comments.length,
      comments_sample: comments.slice(0, 10),
      graph_error: null,
    };
  } catch (error) {
    return {
      success: false,
      post_id: safePostId,
      comments_count: 0,
      comments_sample: [],
      graph_error: {
        message: error?.message || "Unable to load post comments",
        status: error?.status || null,
        code: error?.meta?.code || error?.code || "",
        subcode: error?.meta?.error_subcode || "",
      },
    };
  }
};

export const getMetaPagePostsDebugStatus = async ({ tenantId, limit = 20 } = {}) => {
  const scopedTenantId = numberOrNull(tenantId);
  const row = await getMetaIntegrationConfig({ tenantId: scopedTenantId });
  const token = row ? getTokenForConfig(row) : "";
  const pageId = text(row?.facebook_page_id || row?.page_id || "");
  const safeLimit = Math.max(1, Math.min(20, numberOrNull(limit) || 20));

  if (!pageId) {
    return {
      success: false,
      posts: [],
      graph_error: "Facebook page id is missing",
    };
  }

  if (!token) {
    return {
      success: false,
      posts: [],
      graph_error: "Page access token is missing",
    };
  }

  try {
    const payload = await callMetaGet({
      endpoint: `/${encodeURIComponent(pageId)}/posts`,
      token,
      params: {
        fields: "id,message,created_time,permalink_url",
        limit: String(safeLimit),
      },
    });
    const posts = Array.isArray(payload?.data) ? payload.data.slice(0, safeLimit) : [];
    return {
      success: true,
      posts,
      graph_error: null,
    };
  } catch (error) {
    return {
      success: false,
      posts: [],
      graph_error: {
        message: error?.message || "Unable to load page posts",
        status: error?.status || null,
        code: error?.meta?.code || error?.code || "",
        subcode: error?.meta?.error_subcode || "",
      },
    };
  }
};

