const sendReasoningRecoveryReply = async ({
  config,
  message,
  route = "",
  intent = "",
  productId = "",
  activeProductId = "",
  activeVariantId = "",
  fallbackProductCards = [],
  metadata = {},
  replyCategory = "",
} = {}) => {
  logLegacyRouteTriggered({ message, route, intent, productId, activeProductId, activeVariantId });
  const reasoningReply = await routeMessageThroughAi({ req: null, message, config }).catch((error) => {
    logRouteMessageThroughAiError({
      tenantId: config?.tenant_id,
      conversationId: message?.external_conversation_id || "",
      channel: message?.channel || "",
      message,
      error,
      response: error?.responseBody || null,
    });
    console.warn("[reasoning-route] unified reply failed, falling back to local orchestration", {
      tenant_id: config?.tenant_id,
      conversation_id: message?.external_conversation_id || "",
      route,
      intent,
      message: error?.message || "unified reply failed",
    });
    return null;
  });

  const reasoningText = text(
    reasoningReply?.channel_reply?.text ||
      reasoningReply?.answer ||
      reasoningReply?.text ||
      reasoningReply?.unified_reply?.text ||
      ""
  );
  const reasoningCards = normalizeProductCards(
    reasoningReply?.channel_reply?.product_cards?.length
      ? reasoningReply.channel_reply.product_cards
      : reasoningReply?.product_cards?.length
        ? reasoningReply.product_cards
        : fallbackProductCards,
    { limit: 6 }
  );
  const selectedReplyText = reasoningText || text(fallbackProductCards?.[0]?.name || fallbackProductCards?.[0]?.title || "");
  const generatedImageCardsCount = asArray(
    reasoningReply?.image_cards ||
      reasoningReply?.visual_attachments ||
      reasoningReply?.channel_reply?.image_cards ||
      reasoningReply?.channel_reply?.visual_attachments
  ).length;
  const fallbackReplyUsed = !text(reasoningText) || text(selectedReplyText) !== text(reasoningText);
  const failureReason = !reasoningReply
    ? "unified_reply_request_failed"
    : !text(reasoningText) && reasoningCards.length > 0
      ? "reasoning_text_missing_fallback_to_product_cards"
      : !text(reasoningText) && reasoningCards.length === 0
        ? "reasoning_text_missing_fallback_to_text"
        : /^(?:\s*(?:أيوه|ايوه|موجود|متاح|available|exists)\b)/i.test(text(reasoningText)) && text(reasoningText).length < 30
          ? "reasoning_text_degraded_to_availability_stub"
          : text(reasoningText).length > 0 && text(reasoningText) === text(fallbackProductCards?.[0]?.name || fallbackProductCards?.[0]?.title || "")
            ? "reasoning_text_degraded_to_product_title"
            : "";
  logReasoningFailureRootCause({
    route,
    intent: reasoningReply?.intent || intent,
    activeProductId,
    activeVariantId,
    generatedReasoningText: reasoningText,
    generatedProductCardsCount: reasoningCards.length,
    generatedImageCardsCount,
    failureReason,
    fallbackReplyUsed,
    message,
  });
  logReasoningRouteUsed({
    message,
    route: `reasoning_${route || "recovery"}`,
    intent: reasoningReply?.intent || intent,
    productId: reasoningCards[0]?.product_id || productId,
    activeProductId,
    activeVariantId,
  });

  if (reasoningCards.length) {
    const result = await sendAndLogProductCards({
      config,
      message,
      productCards: reasoningCards,
      detectedIntent: reasoningReply?.intent || intent || "REASONING_RECOVERY",
      introText: selectedReplyText,
      metadata: {
        reasoning_recovery: true,
        legacy_route: route,
        route_used: `reasoning_${route || "recovery"}`,
        ...metadata,
      },
    });
    return result ? { handled: true, reason: `reasoning_${route || "recovery"}`, reply_preview: selectedReplyText, answer: selectedReplyText } : null;
  }

  const result = await sendAndLogMetaText({
    config,
    message,
    text: selectedReplyText,
    detectedIntent: reasoningReply?.intent || intent || "REASONING_RECOVERY",
    metadata: {
      reasoning_recovery: true,
      legacy_route: route,
      route_used: `reasoning_${route || "recovery"}`,
      ...metadata,
    },
  });
  return result ? { handled: true, reason: `reasoning_${route || "recovery"}`, reply_preview: selectedReplyText, answer: selectedReplyText } : null;
};

const isMetaThreadControlConflict = (error = null) => {
  const code = Number(error?.code || error?.meta?.code || error?.metaResponse?.error?.code || 0);
  const message = text(error?.message || error?.meta?.message || error?.metaResponse?.error?.message || "");
  return code === 10 && /another app|currently controls|thread control|تطبيق\s*(?:ًا|ا)?\s*آخر.*يتحكم|التحكم.*(?:المحادثة|سلسلة)/i.test(message);
};

const postMetaMessageWithThreadControl = async ({ token, recipientId, body = {}, sendContext = {} }) => {
  const isInstagramBusinessLogin =
    text(sendContext.channel) === AI_AGENT_CHANNELS.INSTAGRAM && sendContext.instagram_business_login === true;
  const send = () => {
    if (isInstagramBusinessLogin) {
      const instagramAccountId = text(sendContext.resolved_instagram_account_id);
      if (!instagramAccountId) {
        throw Object.assign(new Error("Instagram Business Account ID is missing."), { status: 409, code: "INSTAGRAM_ACCOUNT_ID_MISSING" });
      }
      const { messaging_type: _messagingType, ...instagramBody } = body || {};
      return callInstagramGraph({
        endpoint: `/${encodeURIComponent(instagramAccountId)}/messages`,
        token,
        method: "POST",
        body: instagramBody,
      });
    }
    return callMetaPost({ endpoint: "/me/messages", token, body });
  };
  try {
    return await send();
  } catch (error) {
    const isMessenger = text(sendContext.channel || AI_AGENT_CHANNELS.FACEBOOK_MESSENGER) === AI_AGENT_CHANNELS.FACEBOOK_MESSENGER;
    if (!isMessenger || !isMetaThreadControlConflict(error)) throw error;
    console.warn("[meta-send] thread control conflict, taking control", {
      pageId: maskIdForLog(sendContext.resolved_page_id || ""),
      recipientId: maskIdForLog(recipientId),
      code: error?.code || error?.meta?.code || "",
    });
    try {
      await callMetaPost({
        endpoint: "/me/take_thread_control",
        token,
        body: {
          recipient: { id: recipientId },
          metadata: "M1 AI Inbox",
        },
      });
      console.log("[meta-send] thread control acquired", {
        pageId: maskIdForLog(sendContext.resolved_page_id || ""),
        recipientId: maskIdForLog(recipientId),
      });
      return await send();
    } catch (threadControlError) {
      error.threadControlError = threadControlError?.message || "Unable to take Messenger thread control";
      error.code = error?.code || error?.meta?.code || "META_THREAD_CONTROL_CONFLICT";
      throw error;
    }
  }
};

const postMetaMessage = async ({ token, recipientId, messageText, sendContext = {}, quickReplies = [] }) => {
  console.log("[meta-send] graphApiCalled", {
    channel: sendContext.channel || AI_AGENT_CHANNELS.FACEBOOK_MESSENGER,
    pageId: maskIdForLog(sendContext.resolved_page_id || ""),
    recipientId: maskIdForLog(recipientId),
    psid: maskIdForLog(sendContext.resolved_recipient_psid || recipientId),
    tokenPresent: Boolean(text(token)),
    payloadType: "text",
  });
  console.log("ai_inbox_send_graph_request", {
    recipient_id: maskIdForLog(recipientId),
    resolved_recipient_psid: maskIdForLog(sendContext.resolved_recipient_psid || recipientId),
    resolved_page_id: maskIdForLog(sendContext.resolved_page_id || ""),
    resolved_customer_id: maskIdForLog(sendContext.resolved_customer_id || recipientId),
    resolved_sender_id: maskIdForLog(sendContext.resolved_sender_id || recipientId),
    message_length: text(messageText).length,
    message_type: "text",
  });
  let payload;
  try {
    payload = await postMetaMessageWithThreadControl({
      token,
      recipientId,
      sendContext,
      body: {
        recipient: { id: recipientId },
        messaging_type: "RESPONSE",
        message: {
          text: text(messageText).slice(0, 2000),
          ...(Array.isArray(quickReplies) && quickReplies.length ? { quick_replies: quickReplies } : {}),
        },
      },
    });
  } catch (error) {
    console.error("[meta-send] failed", {
      status: error?.status || "",
      code: error?.code || error?.meta?.code || "",
      subcode: error?.meta?.error_subcode || "",
      message: error?.message || "Meta Send API failed",
      fbtrace_id: error?.meta?.fbtrace_id || "",
      payloadType: "text",
    });
    console.error("[meta-inbox] graph_send_error", {
      status: error?.status || "",
      code: error?.code || error?.meta?.code || "",
      subcode: error?.meta?.error_subcode || "",
      type: error?.meta?.type || "",
      message: error?.message || "Meta Send API failed",
      fbtrace_id: error?.meta?.fbtrace_id || "",
    });
    throw error;
  }
  console.log("[meta-send] success", {
    status: 200,
    recipientId: maskIdForLog(recipientId),
    message_id: payload?.message_id || "",
    payloadType: "text",
  });
  console.log("[meta-inbox] graph_send_success", {
    recipient_id: maskIdForLog(recipientId),
    message_id: payload?.message_id || "",
    recipient_id_returned: maskIdForLog(payload?.recipient_id || ""),
  });
  return payload;
};

