const resolveSocialCommentSalesFlowProductData = async ({ tenantId = null, productId = null } = {}) => {
  const safeProductId = Number(productId || 0);
  if (!Number.isFinite(safeProductId) || safeProductId <= 0) return null;
  const safeTenantId = Number(tenantId || 0);
  return withSocialCommentRuntimeCache({
    cacheName: "social_comment_sales_context",
    cacheKey: buildSocialCommentRuntimeCacheKey(safeTenantId, safeProductId),
    metadata: {
      tenant_id: safeTenantId,
      product_id: safeProductId,
    },
    loader: async () => {
      const productResult = await db.query(
        `
        SELECT
          id,
          name,
          slug,
          canonical_slug,
          image_url,
          selling_price,
          sale_price,
          price
        FROM products
        WHERE id = $1
          AND ($2::bigint <= 0 OR tenant_id = $2::bigint OR tenant_id IS NULL)
        LIMIT 1
        `,
        [safeProductId, safeTenantId]
      ).catch(() => ({ rows: [] }));
      const product = productResult.rows?.[0] || null;
      if (!product) return null;
      const [resolvedLink, priceUsed] = await Promise.all([
        resolveStorefrontProductLink({
          tenantId: safeTenantId,
          product: {
            id: product.id,
            product_id: product.id,
            name: product.name || "",
            slug: product.slug || "",
            canonical_slug: product.canonical_slug || "",
          },
        }).catch(() => null),
        resolveSocialCommentSalesFlowPrice({ tenantId: safeTenantId, product }),
      ]);
      return {
        productId: Number(product.id || 0) || null,
        productName: text(product.name || "") || "المنتج",
        priceUsed,
        productLink: ensureAbsoluteSocialProductLink(resolvedLink?.url || resolvedLink?.product_url || ""),
        productImageUrl: text(product.image_url || ""),
      };
    },
  });
};

const resolveSocialCommentSalesFlowDraftOrderData = async ({
  tenantId = null,
  productId = null,
  selectedSize = "",
  selectedColor = "",
} = {}) => {
  const safeProductId = Number(productId || 0);
  if (!Number.isFinite(safeProductId) || safeProductId <= 0) return null;
  const safeTenantId = Number(tenantId || 0);
  const productResult = await db.query(
    `
    SELECT
      id,
      name,
      slug,
      canonical_slug,
      image_url,
      selling_price,
      sale_price,
      price
    FROM products
    WHERE id = $1
      AND ($2::bigint <= 0 OR tenant_id = $2::bigint OR tenant_id IS NULL)
    LIMIT 1
    `,
    [safeProductId, safeTenantId]
  ).catch(() => ({ rows: [] }));
  const productRow = productResult.rows?.[0] || null;
  if (!productRow) return null;
  const variantResult = await db.query(
    `
    SELECT
      id,
      product_id,
      size,
      color,
      sku,
      barcode,
      COALESCE(stock, 0) AS stock,
      price,
      sale_price,
      selling_price
    FROM product_variants
    WHERE product_id = $1
      AND ($2::bigint <= 0 OR tenant_id = $2::bigint OR tenant_id IS NULL)
      AND (
        $3::text = '' OR LOWER(TRIM(COALESCE(size, ''))) = LOWER(TRIM($3::text))
      )
      AND (
        $4::text = '' OR LOWER(TRIM(COALESCE(color, ''))) = LOWER(TRIM($4::text))
      )
    ORDER BY
      CASE
        WHEN $3::text <> '' AND LOWER(TRIM(COALESCE(size, ''))) = LOWER(TRIM($3::text))
         AND ($4::text = '' OR LOWER(TRIM(COALESCE(color, ''))) = LOWER(TRIM($4::text))) THEN 0
        WHEN $3::text = '' AND $4::text = '' THEN 1
        ELSE 2
      END,
      COALESCE(stock, 0) DESC,
      id ASC
    LIMIT 1
    `,
    [safeProductId, safeTenantId, text(selectedSize), text(selectedColor)]
  ).catch(() => ({ rows: [] }));
  const variantRow = variantResult.rows?.[0] || null;
  if (!variantRow) return null;
  const product = {
    id: Number(productRow.id || 0) || null,
    product_id: Number(productRow.id || 0) || null,
    name: text(productRow.name || ""),
    product_name: text(productRow.name || ""),
    slug: text(productRow.slug || ""),
    canonical_slug: text(productRow.canonical_slug || ""),
    image_url: text(productRow.image_url || ""),
    price: moneyNumberOrZero(productRow.price),
    sale_price: moneyNumberOrZero(productRow.sale_price),
    selling_price: moneyNumberOrZero(productRow.selling_price),
    confidence: 1,
  };
  const variant = {
    id: Number(variantRow.id || 0) || null,
    variant_id: Number(variantRow.id || 0) || null,
    product_id: Number(variantRow.product_id || product.id || 0) || null,
    size: text(variantRow.size || ""),
    color: text(variantRow.color || ""),
    name: text([product.name || "المنتج", variantRow.size, variantRow.color].filter(Boolean).join(" / ")),
    sku: text(variantRow.sku || ""),
    barcode: text(variantRow.barcode || ""),
    stock: moneyNumberOrZero(variantRow.stock),
    price: moneyNumberOrZero(variantRow.price),
    sale_price: moneyNumberOrZero(variantRow.sale_price),
    selling_price: moneyNumberOrZero(variantRow.selling_price),
  };
  const resolvedPrice = await resolveSocialProductDisplayPrice({
    tenantId: safeTenantId,
    product,
    linkedProduct: product,
    variants: [variant],
    availableVariants: [variant],
    context: {
      product_id: product.id,
      product_name: product.name,
    },
    callsite: "metaIntegrationService.resolveSocialCommentSalesFlowDraftOrderData",
  }).catch(() => null);
  const unitPrice = moneyNumberOrZero(resolvedPrice?.selected_price);
  return {
    product,
    variant,
    unitPrice,
    productName: product.name || "المنتج",
    productImageUrl: text(product.image_url || ""),
    productLink: "",
    selectedPriceText: text(resolvedPrice?.selected_display_price || ""),
    selectedPriceField: text(resolvedPrice?.selected_field || ""),
    priceTrace: resolvedPrice || null,
  };
};

const createSocialCommentDraftOrder = async ({
  config,
  message,
  salesFlow = {},
  mergedInfo = {},
  productId = null,
  selectedSize = "",
  selectedColor = "",
  postId = "",
  commentId = "",
  shippingProductData = null,
} = {}) => {
  const tenantId = Number(config?.tenant_id || 0);
  const conversationId = text(message?.external_conversation_id || "");
  const platform = text(message?.channel || "");
  const normalizedCustomerPhone = normalizeEgyptPhone(mergedInfo?.customerPhone || salesFlow?.customer_phone || "");
  if (!tenantId || !conversationId || !productId) {
    throw Object.assign(new Error("Missing social comment draft order context"), { status: 400 });
  }
  const idempotencyKey = [
    conversationId,
    text(commentId || ""),
    text(postId || ""),
    String(productId || ""),
    text(selectedSize || ""),
    text(selectedColor || ""),
  ].join("|");
  console.log("SOCIAL_COMMENT_DRAFT_ORDER_CREATE_START", {
    tenant_id: tenantId,
    platform,
    conversation_id: conversationId,
    post_id: text(postId || ""),
    comment_id: text(commentId || ""),
    product_id: Number(productId || 0) || null,
    selected_size: text(selectedSize || ""),
    selected_color: text(selectedColor || ""),
    customer_phone: normalizedCustomerPhone,
    idempotency_key: idempotencyKey,
  });
  const client = await db.connect();
  try {
    const customerName = text(mergedInfo?.customerName || salesFlow?.customer_name || "");
    const customerAddress = text(mergedInfo?.customerAddress || salesFlow?.customer_address || "");
    const governorate = text(mergedInfo?.governorate || salesFlow?.governorate || "");
    const area = text(mergedInfo?.area || salesFlow?.city_area || governorate || "");
    const customer = await resolveOrCreateCustomerAccount(client, {
      tenantId,
      customerId: numberOrNull(salesFlow?.customer_id || message?.customer_id || null),
      name: customerName || "Customer",
      phone: normalizedCustomerPhone,
      address: customerAddress,
    });
    const draftData = await resolveSocialCommentSalesFlowDraftOrderData({
      tenantId,
      productId,
      selectedSize,
      selectedColor,
    });
    if (!draftData?.product || !draftData?.variant) {
      throw Object.assign(new Error("Unable to resolve draft order product variant"), { status: 409, code: "DRAFT_VARIANT_NOT_FOUND" });
    }
    const payload = {
      tenant_id: tenantId,
      channel: platform,
      source: "social_comment_messenger",
      conversation_id: conversationId,
      session_id: conversationId,
      external_customer_id: text(message?.external_customer_id || ""),
      customer_id: customer?.id || null,
      customer_phone: normalizedCustomerPhone,
      customer_name: customerName,
      customer_address: customerAddress,
      governorate,
      city_area: area,
      allow_missing_phone: true,
      allow_out_of_stock_draft: true,
      product: draftData.product,
      variant: draftData.variant,
      size: text(selectedSize || ""),
      color: text(selectedColor || ""),
      unit_price: draftData.unitPrice > 0 ? draftData.unitPrice : null,
      quantity: 1,
      original_customer_message: text(message?.message_text || ""),
      idempotency_key: idempotencyKey,
      metadata: {
        source: "social_comment_messenger",
        status: "pending_staff_review",
        payment_method: "cash_on_delivery",
        payment_status: "unpaid",
        platform,
        conversation_id: conversationId,
        comment_id: text(commentId || ""),
        post_id: text(postId || ""),
        product_id: Number(productId || 0) || null,
        selected_size: text(selectedSize || ""),
        selected_color: text(selectedColor || ""),
        messenger_psid: text(message?.external_customer_id || ""),
        customer_id: customer?.id || null,
        customer_name: customerName,
        customer_phone: normalizedCustomerPhone,
        governorate,
        customer_address: customerAddress,
        sales_flow: salesFlow || {},
        shipping_product_name: text(shippingProductData?.productName || ""),
      },
    };
    console.log("SOCIAL_COMMENT_DRAFT_ORDER_PRICE_INPUT", {
      raw_price: draftData?.priceTrace?.selected_price ?? draftData?.selectedPriceText ?? null,
      parsed_price: draftData.unitPrice > 0 ? draftData.unitPrice : null,
      type: typeof draftData.unitPrice,
    });
    const draft = await createAiOrderDraft(payload);
    const orderId = draft?.order?.id || null;
    const orderStatus = "pending_staff_review";
    if (orderId) {
      const finalized = await db.query(
        `
        UPDATE orders
        SET
          customer_id = COALESCE($3::bigint, customer_id),
          customer_name = COALESCE(NULLIF($4::text, ''), customer_name),
          customer_phone = COALESCE(NULLIF($5::text, ''), customer_phone),
          customer_address = COALESCE(NULLIF($6::text, ''), customer_address),
          governorate = COALESCE(NULLIF($7::text, ''), governorate),
          city_area = COALESCE(NULLIF($8::text, ''), city_area),
          source = COALESCE(NULLIF($9::text, ''), source),
          channel = COALESCE(NULLIF($10::text, ''), channel),
          status = COALESCE(NULLIF($11::text, ''), status),
          payment_status = COALESCE(NULLIF($12::text, ''), payment_status),
          payment_method = COALESCE(NULLIF($13::text, ''), payment_method),
          ai_agent_status = COALESCE(NULLIF($14::text, ''), ai_agent_status),
          ai_agent_metadata = COALESCE(ai_agent_metadata, '{}'::jsonb) || $15::jsonb,
          updated_at = NOW()
        WHERE tenant_id = $1 AND id = $2
        RETURNING *
        `,
        [
          tenantId,
          orderId,
          customer?.id || null,
          customerName,
          normalizedCustomerPhone,
          customerAddress,
          governorate,
          area,
          "social_comment_messenger",
          text(message?.channel || ""),
          orderStatus,
          "unpaid",
          "cash_on_delivery",
          orderStatus,
          json({
            social_comment_messenger: true,
            social_comment_source: "social_comment_messenger",
            draft_order_id: orderId,
            customer_id: customer?.id || null,
            customer_name: customerName,
            customer_phone: normalizedCustomerPhone,
            customer_address: customerAddress,
            governorate,
            city_area: area,
            platform,
            conversation_id: conversationId,
            comment_id: text(commentId || ""),
            post_id: text(postId || ""),
            product_id: Number(productId || 0) || null,
            selected_size: text(selectedSize || ""),
            selected_color: text(selectedColor || ""),
            messenger_psid: text(message?.external_customer_id || ""),
            payment_method: "cash_on_delivery",
            payment_status: "unpaid",
            status: "pending_staff_review",
            source: "social_comment_messenger",
            unit_price: draftData.unitPrice > 0 ? draftData.unitPrice : null,
            duplicate: Boolean(draft?.duplicate),
          }),
        ]
      );
      const orderRow = finalized.rows?.[0] || draft.order || null;
      console.log(draft?.duplicate ? "SOCIAL_COMMENT_DRAFT_ORDER_DUPLICATE" : "SOCIAL_COMMENT_DRAFT_ORDER_CREATED", {
        tenant_id: tenantId,
        platform,
        conversation_id: conversationId,
        post_id: text(postId || ""),
        comment_id: text(commentId || ""),
        product_id: Number(productId || 0) || null,
        order_id: orderRow?.id || orderId || null,
        existing_order_id: draft?.existing_order_id || null,
        customer_id: customer?.id || null,
        duplicate: Boolean(draft?.duplicate),
        selected_size: text(selectedSize || ""),
        selected_color: text(selectedColor || ""),
        customer_phone: normalizedCustomerPhone,
        unit_price: draftData.unitPrice || null,
      });
      return {
        order: orderRow,
        duplicate: Boolean(draft?.duplicate),
        customer,
        product: draftData.product,
        variant: draftData.variant,
        unitPrice: draftData.unitPrice,
      };
    }
    throw Object.assign(new Error("Missing order id after draft creation"), { status: 500 });
  } catch (error) {
    console.log("SOCIAL_COMMENT_DRAFT_ORDER_CREATE_FAILED", {
      tenant_id: tenantId,
      platform,
      conversation_id: conversationId,
      post_id: text(postId || ""),
      comment_id: text(commentId || ""),
      product_id: Number(productId || 0) || null,
      message: error?.message || String(error),
      code: error?.code || "",
    });
    throw error;
  } finally {
    client.release();
  }
};

const buildSocialCommentDraftOrderEligibility = ({
  message = {},
  salesFlow = {},
  mergedInfo = {},
  productId = null,
  selectedSize = "",
  selectedColor = "",
} = {}) => {
  const conversationId = text(message?.external_conversation_id || "");
  const salesFlowStep = text(salesFlow?.step || "");
  const normalizedCustomerPhone = normalizeEgyptPhone(mergedInfo?.customerPhone || salesFlow?.customer_phone || "");
  const customerName = text(mergedInfo?.customerName || salesFlow?.customer_name || "");
  const governorate = text(mergedInfo?.governorate || salesFlow?.governorate || "");
  const customerAddress = text(mergedInfo?.customerAddress || salesFlow?.customer_address || "");
  const hasShippingData = Boolean(customerName && governorate && customerAddress);
  const hasProductId = Boolean(Number(productId || 0) > 0);
  const reasonIfNotEligible = !conversationId
    ? "missing_conversation_id"
    : !hasProductId
      ? "missing_product_id"
      : !text(selectedSize || salesFlow?.selected_size || "")
        ? "missing_selected_size"
        : !hasShippingData
          ? "missing_shipping_data"
          : "";
  return {
    conversation_id: conversationId,
    sales_flow_step: salesFlowStep,
    has_shipping_data: hasShippingData,
    has_product_id: hasProductId,
    selected_size: text(selectedSize || salesFlow?.selected_size || ""),
    selected_color: text(selectedColor || salesFlow?.selected_color || ""),
    customer_phone: normalizedCustomerPhone,
    reason_if_not_eligible: reasonIfNotEligible,
    eligible: !reasonIfNotEligible,
  };
};

const loadSocialCommentSalesFlowVariantRows = async ({
  tenantId = null,
  productId = null,
  selectedSize = "",
  selectedColor = "",
} = {}) => {
  const safeProductId = Number(productId || 0);
  if (!Number.isFinite(safeProductId) || safeProductId <= 0) return [];
  const safeTenantId = Number(tenantId || 0);
  const result = await db.query(
    `
    SELECT
      id,
      size,
      color,
      COALESCE(stock, 0) AS stock
    FROM product_variants
    WHERE product_id = $1
      AND ($2::bigint <= 0 OR tenant_id = $2::bigint OR tenant_id IS NULL)
      AND COALESCE(stock, 0) > 0
      AND ($3::text = '' OR size = $3::text)
      AND ($4::text = '' OR color = $4::text)
    ORDER BY id ASC
    `,
    [safeProductId, safeTenantId, text(selectedSize), text(selectedColor)]
  ).catch(() => ({ rows: [] }));
  return Array.isArray(result.rows) ? result.rows : [];
};

const uniqueSocialCommentColors = (rows = []) =>
  asArray(rows)
    .map((row) => text(row?.color || ""))
    .filter(Boolean)
    .filter((value, index, array) => array.indexOf(value) === index);

const persistSocialCommentSalesFlowState = async ({
  config,
  message,
  productId = null,
  selectedSize = "",
  selectedColor = "",
  step = "",
  extra = {},
  reason = "social_comment_sales_flow",
  callsite = "persistSocialCommentSalesFlowState",
} = {}) => {
  const conversationId = text(message?.external_conversation_id || "");
  if (!conversationId) return null;
  const previousMemory = getConversationMemory(conversationId) || {};
  const oldStep = socialCommentSalesFlowStepFromMemory(previousMemory);
  const nextMemory = updateConversationMemory(conversationId, {
    selectedProductId: Number(productId || 0) || null,
    activeProductId: Number(productId || 0) || null,
    selectedSize: text(selectedSize),
    activeSize: text(selectedSize),
    selectedColor: text(selectedColor),
    activeColor: text(selectedColor),
    last_selected_size: text(selectedSize),
    last_selected_color: text(selectedColor),
    sales_flow: {
      product_id: Number(productId || 0) || null,
      selected_size: text(selectedSize),
      selected_color: text(selectedColor) || null,
      step: text(step),
      source: SOCIAL_COMMENT_SALES_FLOW_SOURCE,
      ...((extra && typeof extra === "object" && !Array.isArray(extra)) ? extra : {}),
    },
  });
  persistAiConversationMemory({
    tenantId: config.tenant_id,
    channel: message.channel,
    conversationId,
    reason,
  });
  const newStep = socialCommentSalesFlowStepFromMemory(nextMemory);
  if (oldStep !== newStep) {
    console.log("SOCIAL_COMMENT_STATE_TRANSITION", {
      old_step: oldStep,
      new_step: newStep,
      reason,
      callsite,
      conversation_id: conversationId,
    });
  }
  updatePersistentCustomerConversationMemory({
    tenantId: config.tenant_id,
    sessionId: conversationId,
    customerPhone: "",
    message: message.message_text || text(selectedSize || selectedColor || ""),
    metadata: {
      channel: message.channel,
      session_id: conversationId,
      sales_flow: nextMemory?.sales_flow || {},
    },
    suggestedProducts: [],
    preferencesPatch: {
      selected_size: text(selectedSize),
      selected_color: text(selectedColor),
      last_product_id: Number(productId || 0) || null,
      sales_flow_step: text(step),
    },
  }).catch(() => {});
  logSocialCommentSalesFlowStateSaved({
    config,
    message,
    productId,
    size: selectedSize,
    color: selectedColor,
    step,
  });
  return nextMemory;
};

const clearSocialCommentSalesFlowState = async ({ config, message, productId = null, selectedSize = "", selectedColor = "" } = {}) => {
  const conversationId = text(message?.external_conversation_id || "");
  if (!conversationId) return null;
  const previousMemory = getConversationMemory(conversationId) || {};
  const oldStep = socialCommentSalesFlowStepFromMemory(previousMemory);
  const nextMemory = updateConversationMemory(conversationId, {
    sales_flow: null,
    selectedSize: "",
    activeSize: "",
    selectedColor: "",
    activeColor: "",
  });
  persistAiConversationMemory({
    tenantId: config.tenant_id,
    channel: message.channel,
    conversationId,
    reason: "social_comment_sales_flow_cancelled",
  });
  updatePersistentCustomerConversationMemory({
    tenantId: config.tenant_id,
    sessionId: conversationId,
    customerPhone: "",
    message: message.message_text || "",
    metadata: {
      channel: message.channel,
      session_id: conversationId,
      sales_flow: null,
    },
    suggestedProducts: [],
    preferencesPatch: {
      selected_color: "",
      sales_flow_step: "",
    },
  }).catch(() => {});
  const newStep = socialCommentSalesFlowStepFromMemory(nextMemory);
  if (oldStep !== newStep) {
    console.log("SOCIAL_COMMENT_STATE_TRANSITION", {
      old_step: oldStep,
      new_step: newStep,
      reason: "social_comment_sales_flow_cancelled",
      callsite: "clearSocialCommentSalesFlowState",
      conversation_id: conversationId,
    });
  }
  console.log("SOCIAL_COMMENT_SALES_FLOW_CANCELLED", {
    tenant_id: config.tenant_id,
    platform: text(message?.channel || ""),
    conversation_id: conversationId,
    session_id: conversationId,
    product_id: Number(productId || 0) || null,
    size: text(selectedSize),
    color: text(selectedColor),
    step: "",
  });
  return nextMemory;
};

const buildSocialCommentCustomerDataMissingPrompt = (missing = []) => {
  const labels = [];
  if (missing.includes("first_name")) labels.push("الاسم");
  if (missing.includes("phone")) labels.push("رقم الهاتف");
  if (missing.includes("governorate")) labels.push("المحافظة");
  if (missing.includes("address")) labels.push("العنوان بالتفصيل");
  return labels.length ? `ممتاز\n\nأرسل ${labels.join("\n")} لاستكمال الطلب.` : "";
};

const buildSocialCommentCustomerDataConfirmation = (info = {}, missing = []) => {
  if (!missing.length) return "";
  const lines = ["تم حفظ البيانات المتاحة ✅"];
  if (text(info.customerName)) lines.push(`الاسم: ${text(info.customerName)}`);
  if (text(info.customerPhone)) lines.push(`الهاتف: ${text(info.customerPhone)}`);
  if (text(info.governorate)) lines.push(`المحافظة: ${text(info.governorate)}`);
  if (text(info.customerAddress)) lines.push(`العنوان: ${text(info.customerAddress)}`);
  lines.push("");
  lines.push(buildSocialCommentCustomerDataMissingPrompt(missing));
  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trim();
};

